/* DAWAH X — ahmad, অধ্যায় 29 · খণ্ড 29 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][29]=[[5601,5601,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏رِشْدِينُ ‏ ‏عَنْ ‏ ‏أَبِي صَخْرٍ حُمَيْدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏سَيَكُونُ فِي هَذِهِ الْأُمَّةِ ‏ ‏مَسْخٌ ‏ ‏أَلَا وَذَاكَ فِي الْمُكَذِّبِينَ بِالْقَدَرِ ‏ ‏وَالزِّنْدِيقِيَّةِ ‏","","",""],[5602,5602,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏بَيْنَا أَنَا نَائِمٌ أُتِيتُ بِقَدَحِ لَبَنٍ فَشَرِبْتُ مِنْهُ ثُمَّ أَعْطَيْتُ ‏ ‏فَضْلِي ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏قَالُوا فَمَا ‏ ‏أَوَّلْتَهُ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ الْعِلْمُ ‏","","",""],[5603,5603,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏وَهْبِ بْنِ كَيْسَانَ ‏ ‏وَكَانَ ‏ ‏وَهْبٌ ‏ ‏أَدْرَكَ ‏ ‏ابْنَ عُمَرَ ‏ ‏لَيْسَ فِي كِتَابِ ‏ ‏ابْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏رَأَى رَاعِيَ غَنَمٍ فِي مَكَانٍ قَبِيحٍ وَقَدْ رَأَى ‏ ‏ابْنُ عُمَرَ ‏ ‏مَكَانًا ‏ ‏أَمْثَلَ ‏ ‏مِنْهُ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَيْحَكَ يَا رَاعِي حَوِّلْهَا فَإِنِّي سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏كُلُّ رَاعٍ مَسْئُولٌ عَنْ رَعِيَّتِهِ ‏","","",""],[5604,5604,"","","‏ ‏حَدَّثَنَا ‏ ‏مُصْعَبٌ ‏ ‏حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏النَّجْشِ ‏","","",""],[5605,5605,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏حُصَيْنٌ يَعْنِي ابْنَ نُمَيْرٍ أَبُو مِحْصَنٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَطِيَّةَ ‏ ‏حَدَّثَنِي ‏ ‏سَالِمٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ يَوْمَ عِيدٍ فَبَدَأَ فَصَلَّى ‏ ‏بِلَا أَذَانٍ وَلَا إِقَامَةٍ ثُمَّ خَطَبَ ‏ ‏قَالَ ‏ ‏وَحَدَّثَنِي ‏ ‏عَطَاءٌ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏مِثْلَ ذَلِكَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ الْمُقَدَّمِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مِحْصَنِ بْنُ نُمَيْرٍ ‏ ‏عَنِ ‏ ‏الْفَضْلِ بْنِ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[5606,5606,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ غَزِيَّةَ ‏ ‏عَنْ ‏ ‏حَرْبِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ يُحِبُّ أَنْ تُؤْتَى رُخَصُهُ كَمَا يَكْرَهُ أَنْ تُؤْتَى مَعْصِيَتُهُ ‏","","",""],[5607,5607,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصٌ يَعْنِي ابْنَ غِيَاثٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كُنَّا نَشْرَبُ وَنَحْنُ قِيَامٌ وَنَأْكُلُ وَنَحْنُ نَمْشِي عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[5608,5608,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏اسْتَلَمَ الْحَجَرَ ثُمَّ قَبَّلَ يَدَهُ وَقَالَ مَا تَرَكْتُهُ مُنْذُ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُهُ ‏","","",""],[5609,5609,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏أُسَامَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏يَذْبَحُ أُضْحِيَّتَهُ بِالْمُصَلَّى ‏ ‏يَوْمَ النَّحْرِ ‏ ‏وَذَكَرَ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَفْعَلُهُ ‏","","",""],[5610,5610,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏وَسَمِعْتُهُ ‏ ‏مِنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عُثَيْمٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْبَيْلَمَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يَجُوزُ فِي الرَّضَاعَةِ مِنْ الشُّهُودِ قَالَ رَجُلٌ أَوْ امْرَأَةٌ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏","","",""],[5611,5611,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عُمَرُ بْنُ حَمْزَةَ ‏ ‏أَخْبَرَنِي ‏ ‏سَالِمٌ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ ‏ ‏بِحَاطِبِ بْنِ أَبِي بَلْتَعَةَ ‏ ‏فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْتَ كَتَبْتَ هَذَا الْكِتَابَ قَالَ نَعَمْ أَمَا وَاللَّهِ يَا رَسُولَ اللَّهِ مَا تَغَيَّرَ الْإِيمَانُ مِنْ قَلْبِي وَلَكِنْ لَمْ يَكُنْ رَجُلٌ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏إِلَّا وَلَهُ ‏ ‏جِذْمٌ ‏ ‏وَأَهْلُ بَيْتٍ يَمْنَعُونَ لَهُ أَهْلَهُ وَكَتَبْتُ كِتَابًا رَجَوْتُ أَنْ يَمْنَعَ اللَّهُ بِذَلِكَ أَهْلِي فَقَالَ ‏ ‏عُمَرُ ‏ ‏ائْذَنْ لِي فِيهِ قَالَ ‏ ‏أَوَ كُنْتَ قَاتِلَهُ قَالَ نَعَمْ إِنْ أَذِنْتَ لِي قَالَ وَمَا يُدْرِيكَ ‏ ‏لَعَلَّهُ قَدْ اطَّلَعَ اللَّهُ إِلَى أَهْلِ ‏ ‏بَدْرٍ ‏ ‏فَقَالَ اعْمَلُوا مَا شِئْتُمْ ‏","","",""],[5612,5612,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏هَارُونَ بْنِ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَخْرُجُ إِلَى الْعِيدَيْنِ مِنْ طَرِيقٍ وَيَرْجِعُ مِنْ طَرِيقٍ أُخْرَى ‏","","",""],[5613,5613,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ ‏ ‏وِتْرٌ ‏ ‏يُحِبُّ ‏ ‏الْوِتْرَ ‏ ‏قَالَ ‏ ‏نَافِعٌ ‏ ‏وَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏لَا يَصْنَعُ شَيْئًا إِلَّا ‏ ‏وِتْرًا ‏","","",""],[5614,5614,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏سَوَّارُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ مُعَاذٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَوْنٍ ‏ ‏قَالَ ‏ ‏أَنَا رَأَيْتُ ‏ ‏غَيْلَانَ يَعْنِي الْقَدَرِيَّ ‏ ‏مَصْلُوبًا عَلَى بَابِ ‏ ‏دِمَشْقَ ‏","","",""],[5615,5615,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏حَدَّثَنِي ‏ ‏أُسَامَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏النَّاسُ كَالْإِبِلِ الْمِائَةِ لَا تَكَادُ ‏ ‏تَرَى فِيهَا ‏ ‏رَاحِلَةً ‏ ‏أَوْ مَتَى ‏ ‏تَرَى فِيهَا ‏ ‏رَاحِلَةً ‏","","",""],[5616,5616,"","","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا نَعْلَمُ شَيْئًا خَيْرًا مِنْ مِائَةٍ مِثْلِهِ إِلَّا الرَّجُلَ الْمُؤْمِنَ ‏","","",""],[5617,5617,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ الْقَاسِمِ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الشَّمْسَ وَالْقَمَرَ لَا يَخْسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ وَلَكِنَّهُمَا ‏ ‏آيَةٌ ‏ ‏مِنْ ‏ ‏آيَاتِ ‏ ‏اللَّهِ تَبَارَكَ وَتَعَالَى فَإِذَا رَأَيْتُمُوهُمَا فَصَلُّوا ‏","","",""],[5618,5618,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ بْنُ جَابِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ يَعْنِي ابْنَ عِصْمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَتْ الصَّلَاةُ خَمْسِينَ وَالْغُسْلُ مِنْ الْجَنَابَةِ سَبْعَ مِرَارٍ وَالْغُسْلُ مِنْ الْبَوْلِ سَبْعَ مِرَارٍ ‏ ‏فَلَمْ يَزَلْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْأَلُ حَتَّى جُعِلَتْ الصَّلَاةُ خَمْسًا وَالْغُسْلُ مِنْ الْجَنَابَةِ مَرَّةً وَالْغُسْلُ مِنْ الْبَوْلِ مَرَّةً ‏","","",""],[5619,5619,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ يَعْنِي ابْنَ خَلِيفَةَ ‏ ‏عَنْ ‏ ‏أَبِي جَنَابٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَبِيعُوا الدِّينَارَ بِالدِّينَارَيْنِ وَلَا الدِّرْهَمَ بِالدِّرْهَمَيْنِ وَلَا ‏ ‏الصَّاعَ ‏ ‏بِالصَّاعَيْنِ ‏ ‏فَإِنِّي أَخَافُ عَلَيْكُمْ الرَّمَاءَ وَالرَّمَاءُ ‏ ‏هُوَ الرِّبَا ‏ ‏فَقَامَ إِلَيْهِ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ الرَّجُلَ يَبِيعُ الْفَرَسَ بِالْأَفْرَاسِ ‏ ‏وَالنَّجِيبَةَ ‏ ‏بِالْإِبِلِ قَالَ لَا بَأْسَ إِذَا كَانَ يَدًا بِيَدٍ ‏","","",""],[5620,5620,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏خَلَفٌ ‏ ‏عَنْ ‏ ‏أَبِي جَنَابٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏كَانَ جِذْعُ نَخْلَةٍ فِي الْمَسْجِدِ يُسْنِدُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ظَهْرَهُ إِلَيْهِ إِذَا كَانَ يَوْمُ جُمُعَةٍ أَوْ حَدَثَ أَمْرٌ يُرِيدُ أَنْ يُكَلِّمَ النَّاسَ فَقَالُوا أَلَا نَجْعَلُ لَكَ يَا رَسُولَ اللَّهِ شَيْئًا كَقَدْرِ قِيَامِكَ قَالَ لَا عَلَيْكُمْ أَنْ تَفْعَلُوا فَصَنَعُوا لَهُ مِنْبَرًا ثَلَاثَ ‏ ‏مَرَاقٍ ‏ ‏قَالَ فَجَلَسَ عَلَيْهِ قَالَ ‏ ‏فَخَارَ ‏ ‏الْجِذْعُ كَمَا ‏ ‏تَخُورُ ‏ ‏الْبَقَرَةُ جَزَعًا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَالْتَزَمَهُ وَمَسَحَهُ حَتَّى سَكَنَ ‏","","",""],[5621,5621,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ اتَّخَذَ خَاتَمًا مِنْ ذَهَبٍ فَلَبِسَهُ فَاتَّخَذَ النَّاسُ خَوَاتِيمَ الذَّهَبِ فَقَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنِّي كُنْتُ أَلْبَسُ هَذَا الْخَاتَمَ وَإِنِّي لَنْ أَلْبَسَهُ أَبَدًا ‏ ‏فَنَبَذَهُ ‏ ‏فَنَبَذَ ‏ ‏النَّاسُ خَوَاتِيمَهُمْ ‏","","",""],[5622,5622,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ بَعْثًا وَأَمَّرَ عَلَيْهِمْ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏فَطَعَنَ بَعْضُ النَّاسِ فِي إِمْرَتِهِ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنْ تَطْعَنُوا فِي إِمْرَتِهِ فَقَدْ تَطْعَنُونَ فِي إِمْرَةِ أَبِيهِ مِنْ قَبْلُ وَايْمُ اللَّهِ إِنْ كَانَ ‏ ‏لَخَلِيقًا ‏ ‏لِلْإِمَارَةِ وَإِنْ كَانَ لَمِنْ أَحَبِّ النَّاسِ إِلَيَّ وَإِنَّ هَذَا لَمِنْ أَحَبِّ النَّاسِ إِلَيَّ بَعْدَهُ ‏","","",""],[5623,5623,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ عَمْرِو بْنِ حَلْحَلَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءِ بْنِ عَلْقَمَةَ ‏ ‏أَنَّهُ ‏ ‏كَانَ جَالِسًا مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏بِالسُّوقِ وَمَعَهُ ‏ ‏سَلَمَةُ بْنُ الْأَزْرَقِ ‏ ‏إِلَى جَنْبِهِ فَمُرَّ بِجِنَازَةٍ يَتْبَعُهَا بُكَاءٌ فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏لَوْ تَرَكَ أَهْلُ هَذَا الْمَيِّتِ الْبُكَاءَ لَكَانَ خَيْرًا لَمَيِّتِهِمْ ‏ ‏فَقَالَ ‏ ‏سَلَمَةُ بْنُ الْأَزْرَقِ ‏ ‏تَقُولُ ذَلِكَ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ نَعَمْ أَقُولُهُ قَالَ إِنِّي سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏وَمَاتَ مَيِّتٌ مِنْ أَهْلِ ‏ ‏مَرْوَانَ ‏ ‏فَاجْتَمَعَ النِّسَاءُ يَبْكِينَ عَلَيْهِ فَقَالَ ‏ ‏مَرْوَانُ ‏ ‏قُمْ يَا ‏ ‏عَبْدَ الْمَلِكِ ‏ ‏فَانْهَهُنَّ أَنْ يَبْكِينَ فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏دَعْهُنَّ فَإِنَّهُ مَاتَ مَيِّتٌ مِنْ آلِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاجْتَمَعَ النِّسَاءُ يَبْكِينَ عَلَيْهِ فَقَامَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏يَنْهَاهُنَّ وَيَطْرُدُهُنَّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعْهُنَّ يَا ‏ ‏ابْنَ الْخَطَّابِ ‏ ‏فَإِنَّ الْعَيْنَ دَامِعَةٌ وَالْفُؤَادَ مُصَابٌ وَإِنَّ الْعَهْدَ حَدِيثٌ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏أَنْتَ سَمِعْتَ هَذَا مِنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ نَعَمْ قَالَ يَأْثُرُهُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ قَالَ فَاللَّهُ وَرَسُولُهُ أَعْلَمُ ‏","","",""],[5624,5624,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَخْبَرَهُ ‏ ‏حَمْزَةُ بْنُ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَنْزَلَ اللَّهُ بِقَوْمٍ عَذَابًا أَصَابَ الْعَذَابُ مَنْ كَانَ فِيهِمْ ثُمَّ بُعِثُوا عَلَى أَعْمَالِهِمْ ‏","","",""],[5625,5625,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏أَبِي الصَّبَّاحِ الْأَيْلِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏يَزِيدَ بْنَ أَبِي سُمَيَّةَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏مَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْإِزَارِ فَهُوَ فِي الْقَمِيصِ ‏","","",""],[5626,5626,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الظُّهْرَ وَالْعَصْرَ وَالْمَغْرِبَ وَالْعِشَاءَ أَيْ ‏ ‏بِالْمُحَصَّبِ ‏ ‏ثُمَّ ‏ ‏هَجَعَ ‏ ‏هَجْعَةً ‏ ‏ثُمَّ دَخَلَ فَطَافَ ‏ ‏بِالْبَيْتِ ‏","","",""],[5627,5627,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ يَعْنِي ابْنَ الطَّبَّاعِ ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ الْيَمَانِيِّ ‏ ‏قَالَ ‏ ‏أَدْرَكْتُ نَاسًا مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُونَ كُلُّ شَيْءٍ بِقَدَرٍ قَالَ وَسَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏يَقُولُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ شَيْءٍ بِقَدَرٍ حَتَّى ‏ ‏الْعَجْزُ ‏ ‏وَالْكَيْسُ ‏","","",""],[5628,5628,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ جُرَيْجٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏رَأَيْتُكَ تَصْنَعُ أَرْبَعًا لَمْ أَرَ أَحَدًا مِنْ أَصْحَابِكَ يَصْنَعُهَا قَالَ مَا هِيَ يَا ‏ ‏ابْنَ جُرَيْجٍ ‏ ‏قَالَ رَأَيْتُكَ لَا ‏ ‏تَمَسُّ ‏ ‏مِنْ ‏ ‏الْأَرْكَانِ ‏ ‏إِلَّا الْيَمَانِيَيْنِ وَرَأَيْتُكَ تَلْبَسُ النِّعَالَ ‏ ‏السِّبْتِيَّةَ ‏ ‏وَرَأَيْتُكَ تَصْبُغُ ‏ ‏بِالصُّفْرَةِ ‏ ‏وَرَأَيْتُكَ إِذَا كُنْتَ ‏ ‏بِمَكَّةَ ‏ ‏أَهَلَّ النَّاسُ إِذَا رَأَوْا الْهِلَالَ وَلَمْ تُهْلِلْ أَنْتَ حَتَّى يَكُونَ ‏ ‏يَوْمُ التَّرْوِيَةِ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَمَّا ‏ ‏الْأَرْكَانُ ‏ ‏فَإِنِّي ‏ ‏لَمْ أَرَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمَسُّ إِلَّا الْيَمَانِيَيْنِ وَأَمَّا النِّعَالُ فَإِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَلْبَسُ النِّعَالَ الَّتِي لَيْسَ فِيهَا شَعَرٌ وَيَتَوَضَّأُ فِيهَا وَأَنَا أُحِبُّ أَنْ أَلْبَسَهَا وَأَمَّا ‏ ‏الصُّفْرَةُ ‏ ‏فَإِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْبُغُ بِهَا وَأَنَا أُحِبُّ أَنْ أَصْبُغَ بِهَا وَأَمَّا الْإِهْلَالُ فَإِنِّي لَمْ أَرَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُهِلُّ حَتَّى ‏ ‏تَنْبَعِثَ ‏ ‏بِهِ ‏ ‏رَاحِلَتُهُ ‏","","",""],[5629,5629,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏وَأَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏بَعَثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏سَرِيَّةٍ ‏ ‏فَلَمَّا لَقِينَا الْعَدُوَّ انْهَزَمْنَا فِي أَوَّلِ ‏ ‏عَادِيَةٍ ‏ ‏فَقَدِمْنَا ‏ ‏الْمَدِينَةَ ‏ ‏فِي ‏ ‏نَفَرٍ ‏ ‏لَيْلًا فَاخْتَفَيْنَا ثُمَّ قُلْنَا لَوْ خَرَجْنَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاعْتَذَرْنَا إِلَيْهِ فَخَرَجْنَا فَلَمَّا لَقِينَاهُ قُلْنَا نَحْنُ ‏ ‏الْفَرَّارُونَ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ ‏ ‏بَلْ أَنْتُمْ ‏ ‏الْعَكَّارُونَ ‏ ‏وَأَنَا ‏ ‏فِئَتُكُمْ ‏ ‏قَالَ ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏وَأَنَا ‏ ‏فِئَةُ ‏ ‏كُلِّ مُسْلِمٍ ‏","","",""],[5630,5630,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ عَبْدِ اللَّهِ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَبَرُّ ‏ ‏الْبِرِّ ‏ ‏صِلَةُ ‏ ‏الْمَرْءِ أَهْلَ وُدِّ أَبِيهِ بَعْدَ إِذْ ‏ ‏يُوَلِّي ‏","","",""],[5631,5631,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏بُكَيْرٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ مَاتَ عَلَى غَيْرِ طَاعَةِ اللَّهِ مَاتَ وَلَا حُجَّةَ لَهُ وَمَنْ مَاتَ وَقَدْ ‏ ‏نَزَعَ ‏ ‏يَدَهُ مِنْ ‏ ‏بَيْعَةٍ ‏ ‏كَانَتْ مِيتَتُهُ مِيتَةَ ضَلَالَةٍ ‏","","",""],[5632,5632,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ أَبِي عِمْرَانَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَلَّى صَلَاةَ الصُّبْحِ فَلَهُ ‏ ‏ذِمَّةُ ‏ ‏اللَّهِ فَلَا ‏ ‏تُخْفِرُوا ‏ ‏اللَّهَ ‏ ‏ذِمَّتَهُ ‏ ‏فَإِنَّهُ مَنْ ‏ ‏أَخْفَرَ ‏ ‏ذِمَّتَهُ ‏ ‏طَلَبَهُ اللَّهُ حَتَّى ‏ ‏يُكِبَّهُ ‏ ‏عَلَى وَجْهِهِ ‏","","",""],[5633,5633,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى يَعْنِي ابْنَ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هَانِئٍ ‏ ‏عَنْ ‏ ‏عَبَّاسِ بْنِ جُلَيْدٍ الْحَجْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ كَمْ يُعْفَى عَنْ الْمَمْلُوكِ قَالَ فَصَمَتَ عَنْهُ ثُمَّ أَعَادَ فَصَمَتَ عَنْهُ ثُمَّ أَعَادَ فَقَالَ ‏ ‏يُعْفَى عَنْهُ كُلَّ يَوْمٍ سَبْعِينَ مَرَّةً ‏","","",""],[5634,5634,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنِ ‏ ‏أَبِي الْأَسْوَدِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اشْتَرَى طَعَامًا بِكَيْلٍ أَوْ وَزْنٍ فَلَا يَبِيعُهُ حَتَّى يَقْبِضَهُ ‏","","",""],[5635,5635,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلُ بْنُ إِسْمَاعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّكُمْ رَاعٍ وَكُلُّكُمْ مَسْئُولٌ عَنْ رَعِيَّتِهِ فَالْأَمِيرُ رَاعٍ عَلَى رَعِيَّتِهِ وَهُوَ مَسْئُولٌ عَنْهُمْ وَالرَّجُلُ رَاعٍ عَلَى أَهْلِ بَيْتِهِ وَهُوَ مَسْئُولٌ عَنْهُمْ وَالْعَبْدُ رَاعٍ عَلَى مَالِ سَيِّدِهِ وَهُوَ مَسْئُولٌ عَنْهُ وَالْمَرْأَةُ رَاعِيَةٌ عَلَى بَيْتِ زَوْجِهَا وَمَسْئُولَةٌ عَنْهُ ‏","","",""],[5636,5636,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ هَذِهِ الْأُمَّةِ ‏ ‏أَوْ قَالَ أُمَّتِي ‏ ‏وَمَثَلُ ‏ ‏الْيَهُودِ ‏ ‏وَالنَّصَارَى ‏ ‏كَمَثَلِ رَجُلٍ قَالَ مَنْ يَعْمَلُ لِي مِنْ ‏ ‏غُدْوَةٍ ‏ ‏إِلَى نِصْفِ النَّهَارِ عَلَى ‏ ‏قِيرَاطٍ ‏ ‏قَالَتْ ‏ ‏الْيَهُودُ ‏ ‏نَحْنُ فَفَعَلُوا فَقَالَ فَمَنْ يَعْمَلُ لِي مِنْ نِصْفِ النَّهَارِ إِلَى الْعَصْرِ عَلَى ‏ ‏قِيرَاطٍ ‏ ‏قَالَتْ ‏ ‏النَّصَارَى ‏ ‏نَحْنُ فَعَمِلُوا وَأَنْتُمْ الْمُسْلِمُونَ تَعْمَلُونَ مِنْ صَلَاةِ الْعَصْرِ إِلَى اللَّيْلِ عَلَى ‏ ‏قِيرَاطَيْنِ ‏ ‏فَغَضِبَتْ ‏ ‏الْيَهُودُ ‏ ‏وَالنَّصَارَى ‏ ‏فَقَالُوا نَحْنُ أَكْثَرُ عَمَلًا وَأَقَلُّ أَجْرًا فَقَالَ هَلْ ظَلَمْتُكُمْ مِنْ أَجْرِكُمْ شَيْئًا قَالُوا لَا قَالَ فَذَاكَ ‏ ‏فَضْلِي ‏ ‏أُوتِيهِ مَنْ أَشَاءُ ‏ ‏قَالَ ‏ ‏سَمِعْت ‏ ‏مِنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏هَذَا الْحَدِيثَ فَلَمْ أَكْتُبْهُ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَمِلَتْ ‏ ‏الْيَهُودُ ‏ ‏كَذَا ‏ ‏وَالنَّصَارَى ‏ ‏كَذَا نَحْوَ حَدِيثِ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏فِي قِصَّةِ ‏ ‏الْيَهُودِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَاه ‏ ‏مُؤَمَّلٌ ‏ ‏أَيْضًا ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏نَحْوَ حَدِيثِ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَيْضًا ‏","","",""],[5637,5637,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَوْمَأَ ‏ ‏بِيَدِهِ نَحْوَ الْمَشْرِقِ ‏ ‏هَاهُنَا ‏ ‏الْفِتْنَةُ ‏ ‏هَاهُنَا ‏ ‏الْفِتْنَةُ ‏ ‏حَيْثُ يَطْلُعُ قَرْنُ الشَّيْطَانِ ‏","","",""],[5638,5638,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا لَمْ يَجِدْ الْمُحْرِمُ النَّعْلَيْنِ فَلْيَلْبِسْ ‏ ‏الْخُفَّيْنِ ‏ ‏يَقْطَعُهُمَا أَسْفَلَ مِنْ ‏ ‏الْكَعْبَيْنِ ‏","","",""],[5639,5639,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏إِذَا ذُكِرَ عِنْدَهُ ‏ ‏الْبَيْدَاءُ ‏ ‏يَسُبُّهَا وَيَقُولُ إِنَّمَا ‏ ‏أَحْرَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏ذِي الْحُلَيْفَةِ ‏","","",""],[5640,5640,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ مُحَمَّدٍ يَعْنِي ابْنَ زَيْدِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ يَعْلَمُ النَّاسُ مَا فِي الْوَحْدَةِ مَا ‏ ‏سَرَى ‏ ‏أَحَدٌ بِلَيْلٍ وَحْدَهُ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَثَنَا بِهِ ‏ ‏مُؤَمَّلٌ ‏ ‏مَرَّةً أُخْرَى وَلَمْ يَقُلْ عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏سَمِعْت ‏ ‏أَبِي ‏ ‏يَقُولُ ‏ ‏قَدْ سَمِعَ ‏ ‏مُؤَمَّلٌ ‏ ‏مِنْ ‏ ‏عُمَرَ بْنِ مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏يَعْنِي أَحَادِيثَ ‏ ‏وَسَمِعَ أَيْضًا مِنْ ‏ ‏ابْنِ جُرَيْجٍ ‏","","",""],[5641,5641,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَجَلُكُمْ فِي ‏ ‏أَجَلِ ‏ ‏مَنْ كَانَ قَبْلَكُمْ كَمَا بَيْنَ صَلَاةِ الْعَصْرِ إِلَى غُرُوبِ الشَّمْسِ ‏","","",""],[5642,5642,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ ‏} { ‏فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ ‏} ‏فِي ‏ ‏الرَّشْحِ ‏ ‏إِلَى أَنْصَافِ آذَانِهِمْ ‏","","",""],[5643,5643,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏قَالَ ‏ ‏قَالَ لِي ‏ ‏مُحَارِبُ بْنُ دِثَارٍ ‏ ‏مَا سَمِعْتَ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏يَذْكُرُ عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فِي ‏ ‏الْكَوْثَرِ ‏ ‏فَقُلْتُ سَمِعْتُهُ يَقُولُ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏هَذَا الْخَيْرُ الْكَثِيرُ ‏ ‏فَقَالَ ‏ ‏مُحَارِبٌ ‏ ‏سُبْحَانَ اللَّهِ مَا أَقَلَّ مَا يَسْقُطُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏قَوْلٌ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ لَمَّا أُنْزِلَتْ ‏ ‏إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ نَهَرٌ فِي الْجَنَّةِ حَافَتَاهُ مِنْ ذَهَبٍ يَجْرِي عَلَى جَنَادِلِ ‏ ‏الدُّرِّ ‏ ‏وَالْيَاقُوتِ شَرَابُهُ أَحْلَى مِنْ الْعَسَلِ وَأَشَدُّ بَيَاضًا مِنْ اللَّبَنِ وَأَبْرَدُ مِنْ الثَّلْجِ وَأَطْيَبُ مِنْ رِيحِ ‏ ‏الْمِسْكِ ‏ ‏قَالَ ‏ ‏صَدَقَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏هَذَا وَاللَّهِ الْخَيْرُ الْكَثِيرُ ‏","","",""],[5644,5644,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَالَ لِأَخِيهِ يَا كَافِرُ فَقَدْ ‏ ‏بَاءَ ‏ ‏بِهَا أَحَدُهُمَا ‏","","",""],[5645,5645,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يُنْصَبُ لِكُلِّ غَادِرٍ ‏ ‏لِوَاءٌ ‏ ‏يَوْمَ الْقِيَامَةِ ‏","","",""],[5646,5646,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏حَرَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَبِيذَ ‏ ‏الْجَرِّ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبَّاسٍ ‏ ‏فَأَخْبَرْتُهُ فَقَالَ ‏ ‏صَدَقَ ‏ ‏ابْنُ عُمَرَ ‏ ‏قَالَ ‏ ‏قُلْتُ مَا ‏ ‏الْجَرُّ ‏ ‏قَالَ ‏ ‏كُلُّ شَيْءٍ يُصْنَعُ مِنْ ‏ ‏الْمَدَرِ ‏","","",""],[5647,5647,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْوِصَالِ ‏ ‏فَقَالَ أَوَلَسْتَ ‏ ‏تُوَاصِلُ ‏ ‏قَالَ إِنِّي أُطْعَمُ وَأُسْقَى ‏","","",""],[5648,5648,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏سَمِعْتُ ‏ ‏مَالِكًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْخَيْلُ ‏ ‏مَعْقُودٌ ‏ ‏فِي ‏ ‏نَوَاصِيهَا ‏ ‏الْخَيْرُ إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[5649,5649,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ ‏ ‏سَرِيَّةً ‏ ‏قِبَلَ ‏ ‏نَجْدٍ ‏ ‏فِيهَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏فَكَانَتْ سُهْمَانُهُمْ اثْنَيْ عَشَرَ بَعِيرًا ‏ ‏وَنُفِّلُوا ‏ ‏بَعِيرًا بَعِيرًا ‏","","",""],[5650,5650,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَعْتَقَ شِرْكًا فِي عَبْدٍ فَكَانَ لَهُ مَالٌ يَبْلُغُ ثَمَنَ الْعَبْدِ فَإِنَّهُ يُقَوَّمُ عَلَيْهِ قِيمَةَ ‏ ‏عَدْلٍ ‏ ‏فَيُعْطَى شُرَكَاؤُهُ حِصَصَهُمْ وَعَتَقَ الْعَبْدُ عَلَيْهِ وَإِلَّا فَقَدْ عَتَقَ مَا عَتَقَ ‏","","",""],[5651,5651,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةُ الْجَمَاعَةِ تَفْضُلُ عَنْ صَلَاةِ ‏ ‏الْفَذِّ ‏ ‏بِسَبْعٍ وَعِشْرِينَ دَرَجَةً ‏","","",""],[5652,5652,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَاخَ ‏ ‏بِالْبَطْحَاءِ ‏ ‏الَّتِي ‏ ‏بِذِي الْحُلَيْفَةِ ‏ ‏فَصَلَّى بِهَا ‏ ‏وَأَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ يَفْعَلُ ذَلِكَ ‏","","",""],[5653,5653,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّمَا ‏ ‏مَثَلُ صَاحِبِ الْقُرْآنِ كَمَثَلِ صَاحِبِ الْإِبِلِ ‏ ‏الْمُعَقَّلَةِ ‏ ‏فَإِنْ تَعَاهَدَهَا أَمْسَكَهَا وَإِنْ أَطْلَقَهَا ذَهَبَتْ ‏","","",""],[5654,5654,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كُنَّا نَبْتَاعُ الطَّعَامَ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَبْعَثُ عَلَيْنَا مَنْ يَأْمُرُنَا بِنَقْلِهِ مِنْ الْمَكَانِ الَّذِي ابْتَعْنَاهُ فِيهِ إِلَى مَكَانٍ سِوَاهُ قَبْلَ أَنْ نَبِيعَهُ ‏","","",""],[5655,5655,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِقَتْلِ الْكِلَابِ وَقَالَ مَنْ اقْتَنَى كَلْبًا إِلَّا كَلْبَ مَاشِيَةٍ أَوْ ضَارِيَةٍ نَقَصَ مِنْ عَمَلِهِ كُلَّ يَوْمٍ ‏ ‏قِيرَاطَانِ ‏","","",""],[5656,5656,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَحَدَكُمْ إِذَا مَاتَ عُرِضَ عَلَيْهِ مَقْعَدُهُ ‏ ‏بِالْغَدَاةِ ‏ ‏وَالْعَشِيِّ إِنْ كَانَ مِنْ أَهْلِ الْجَنَّةِ فَمِنْ أَهْلِ الْجَنَّةِ وَإِنْ كَانَ مِنْ أَهْلِ النَّارِ فَمِنْ أَهْلِ النَّارِ فَيُقَالُ هَذَا مَقْعَدُكَ حَتَّى يَبْعَثَكَ اللَّهُ إِلَيْهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[5657,5657,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنُ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏وَإِسْحَاقُ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ ‏ ‏الْكَعْبَةَ ‏ ‏وَعُثْمَانُ بْنُ طَلْحَةَ ‏ ‏وَأُسَامَةُ بْنُ زَيْدٍ ‏ ‏وَبِلَالٌ ‏ ‏فَأَغْلَقَهَا فَلَمَّا خَرَجَ سَأَلْتُ ‏ ‏بِلَالًا ‏ ‏مَاذَا صَنَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَرَكَ عَمُودَيْنِ عَنْ يَمِينِهِ وَعَمُودًا عَنْ يَسَارِهِ وَثَلَاثَةَ أَعْمِدَةٍ خَلْفَهُ ثُمَّ صَلَّى وَبَيْنَهُ وَبَيْنَ الْقِبْلَةِ ثَلَاثَةُ أَذْرُعٍ ‏ ‏قَالَ ‏ ‏إِسْحَاقُ ‏ ‏وَكَانَ ‏ ‏الْبَيْتُ ‏ ‏يَوْمَئِذٍ عَلَى سِتَّةِ أَعْمِدَةٍ وَلَمْ يَذْكُرْ الَّذِي بَيْنَهُ وَبَيْنَ الْقِبْلَةِ ‏","","",""],[5658,5658,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانُوا يَتَوَضَّئُونَ جَمِيعًا قُلْتُ ‏ ‏لِمَالِكٍ ‏ ‏الرِّجَالُ وَالنِّسَاءُ قَالَ نَعَمْ قُلْتُ زَمَنَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ ‏","","",""],[5659,5659,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَرَادَتْ أَنْ تَشْتَرِيَ جَارِيَةً تُعْتِقُهَا قَالَ أَهْلُهَا نَبِيعُكِ عَلَى أَنَّ ‏ ‏وَلَاءَهَا ‏ ‏لَنَا فَذَكَرَتْ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَا يَمْنَعْكِ ذَلِكَ فَإِنَّ ‏ ‏الْوَلَاءَ ‏ ‏لِمَنْ أَعْتَقَ ‏","","",""],[5660,5660,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا حَقُّ امْرِئٍ لَهُ شَيْءٌ ‏ ‏يُوصِي فِيهِ يَبِيتُ لَيْلَتَيْنِ إِلَّا وَوَصِيَّتُهُ مَكْتُوبَةٌ عِنْدَهُ ‏","","",""],[5661,5661,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِأَصْحَابِهِ ‏ ‏لَا تَدْخُلُوا عَلَى هَؤُلَاءِ الْقَوْمِ الْمُعَذَّبِينَ إِلَّا أَنْ تَكُونُوا بَاكِينَ فَإِنْ لَمْ تَكُونُوا بَاكِينَ فَلَا تَدْخُلُوا عَلَيْهِمْ أَنْ يُصِيبَكُمْ مِثْلُ مَا أَصَابَهُمْ ‏","","",""],[5662,5662,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَحَرَّوْا ‏ ‏لَيْلَةَ الْقَدْرِ فِي السَّبْعِ الْأَوَاخِرِ مِنْ رَمَضَانَ ‏","","",""],[5663,5663,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا ‏ ‏رَجُلٍ قَالَ لِأَخِيهِ يَا كَافِرُ فَقَدْ ‏ ‏بَاءَ ‏ ‏بِهَا أَحَدُهُمَا ‏","","",""],[5664,5664,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا النَّاسُ ‏ ‏بِقُبَاءَ ‏ ‏فِي صَلَاةِ الصُّبْحِ إِذْ أَتَاهُمْ ‏ ‏آتٍ ‏ ‏فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُنْزِلَ عَلَيْهِ قُرْآنٌ اللَّيْلَةَ وَقَدْ أُمِرَ أَنْ يَسْتَقْبِلَ ‏ ‏الْكَعْبَةَ ‏ ‏فَاسْتَقْبِلُوهَا وَكَانَتْ وُجُوهُهُمْ إِلَى ‏ ‏الشَّامِ ‏ ‏فَاسْتَدَارُوا إِلَى ‏ ‏الْكَعْبَةِ ‏","","",""],[5665,5665,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏قَطَنِ بْنِ وَهْبٍ ‏ ‏أَوْ ‏ ‏وَهْبِ بْنِ قَطَنٍ اللَّيْثِيِّ ‏ ‏شَكَّ ‏ ‏إِسْحَاقُ ‏ ‏عَنْ ‏ ‏يُحَنَّسَ ‏ ‏مَوْلَى ‏ ‏الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏ابْنِ عُمَرَ ‏ ‏إِذْ أَتَتْهُ مَوْلَاةٌ لَهُ فَذَكَرَتْ شِدَّةَ ‏ ‏الْحَالِ ‏ ‏وَأَنَّهَا تُرِيدُ أَنْ تَخْرُجَ مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏فَقَالَ لَهَا اجْلِسِي فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَصْبِرُ أَحَدُكُمْ عَلَى ‏ ‏لَأْوَائِهَا ‏ ‏وَشِدَّتِهَا إِلَّا كُنْتُ لَهُ شَفِيعًا ‏ ‏أَوْ شَهِيدًا ‏ ‏يَوْمَ الْقِيَامَةِ ‏","","",""],[5666,5666,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏قَالَ سَأَلْتُ ‏ ‏مالِكًا ‏ ‏عَنْ الرَّجُلِ ‏ ‏يُوتِرُ ‏ ‏وَهُوَ رَاكِبٌ ‏ ‏فَقَالَ أَخْبَرَنِي ‏ ‏أَبُو بَكْرِ بْنُ عُمَرَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ بْنِ الْخَطَّابِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْتَرَ ‏ ‏وَهُوَ رَاكِبٌ ‏","","",""],[5667,5667,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَلَاةِ اللَّيْلِ فَقَالَ مَثْنَى مَثْنَى فَإِذَا خَشِيتَ الصُّبْحَ فَوَاحِدَةً ‏","","",""],[5668,5668,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏الْيَهُودَ ‏ ‏إِذَا سَلَّمُوا عَلَيْكُمْ قَالُوا ‏ ‏السَّامُ ‏ ‏عَلَيْكُمْ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْ وَعَلَيْكَ ‏","","",""],[5669,5669,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏مُلَازِمُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ بَدْرٍ ‏ ‏أَنَّهُ ‏ ‏خَرَجَ فِي نَفَرٍ مِنْ أَصْحَابِهِ حُجَّاجًا حَتَّى وَرَدُوا ‏ ‏مَكَّةَ ‏ ‏فَدَخَلُوا الْمَسْجِدَ فَاسْتَلَمُوا الْحَجَرَ ثُمَّ طُفْنَا ‏ ‏بِالْبَيْتِ ‏ ‏أُسْبُوعًا ثُمَّ صَلَّيْنَا خَلْفَ ‏ ‏الْمَقَامِ ‏ ‏رَكْعَتَيْنِ فَإِذَا رَجُلٌ ضَخْمٌ فِي ‏ ‏إِزَارٍ ‏ ‏وَرِدَاءٍ يُصَوِّتُ بِنَا عِنْدَ الْحَوْضِ فَقُمْنَا إِلَيْهِ وَسَأَلْتُ عَنْهُ فَقَالُوا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَلَمَّا أَتَيْنَاهُ قَالَ مَنْ أَنْتُمْ قُلْنَا أَهْلُ الْمَشْرِقِ وَثَمَّ أَهْلُ ‏ ‏الْيَمَامَةِ ‏ ‏قَالَ فَحُجَّاجٌ أَمْ عُمَّارٌ قُلْتُ بَلْ حُجَّاجٌ قَالَ فَإِنَّكُمْ قَدْ نَقَضْتُمْ حَجَّكُمْ قُلْتُ قَدْ حَجَجْتُ مِرَارًا فَكُنْتُ أَفْعَلُ كَذَا قَالَ فَانْطَلَقْنَا مَكَانَنَا حَتَّى يَأْتِيَ ‏ ‏ابْنُ عُمَرَ ‏ ‏فَقُلْتُ يَا ‏ ‏ابْنَ عُمَرَ ‏ ‏إِنَّا قَدِمْنَا فَقَصَصْنَا عَلَيْهِ قِصَّتَنَا وَأَخْبَرْنَاهُ مَا قَالَ إِنَّكُمْ نَقَضْتُمْ حَجَّكُمْ قَالَ أُذَكِّرُكُمْ بِاللَّهِ أَخَرَجْتُمْ حُجَّاجًا قُلْنَا نَعَمْ فَقَالَ وَاللَّهِ لَقَدْ حَجَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏كُلُّهُمْ فَعَلَ مِثْلَ مَا فَعَلْتُمْ ‏","","",""],[5670,5670,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏مَهْدِيٌّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي يَعْقُوبَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نُعْمٍ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا عِنْدَ ‏ ‏ابْنِ عُمَرَ ‏ ‏فَجَاءَهُ رَجُلٌ يَسْأَلُ عَنْ دَمِ الْبَعُوضِ فَقَالَ لَهُ ‏ ‏ابْنُ عُمَرَ ‏ ‏مِمَّنْ أَنْتَ قَالَ أَنَا مِنْ أَهْلِ ‏ ‏الْعِرَاقِ ‏ ‏قَالَ انْظُرُوا إِلَى هَذَا يَسْأَلُنِي عَنْ دَمِ الْبَعُوضِ وَقَدْ قَتَلُوا ابْنَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏هُمَا رَيْحَانَتِي مِنْ الدُّنْيَا ‏","","",""],[5671,5671,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏رَافِعِ بْنِ حُنَيْنٍ أَبِي الْمُغِيرَةِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَنَّهُ ‏ ‏رَأَى مَذْهَبًا لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُوَاجَهَةَ الْقِبْلَةِ ‏","","",""],[5672,5672,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَدَقَةُ ‏ ‏الْفِطْرِ عَلَى كُلِّ مُسْلِمٍ صَغِيرٍ أَوْ كَبِيرٍ حُرٍّ أَوْ عَبْدٍ ذَكَرٍ أَوْ أُنْثَى ‏ ‏صَاعٌ ‏ ‏مِنْ تَمْرٍ أَوْ ‏ ‏صَاعٌ ‏ ‏مِنْ شَعِيرٍ ‏","","",""],[5673,5673,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَرْمُلُ ‏ ‏ثَلَاثَةَ أَشْوَاطٍ مِنْ الْحَجَرِ إِلَى الْحَجَرِ وَيَمْشِي أَرْبَعَةً وَيُخْبِرُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَفْعَلُهُ ‏","","",""],[5674,5674,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَرْمِي الْجَمْرَةَ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏رَاكِبًا وَسَائِرَ ذَلِكَ مَاشِيًا وَيُخْبِرُهُمْ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَفْعَلُ ذَلِكَ ‏","","",""],[5675,5675,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ ‏ ‏لَا يَسْتَلِمُ شَيْئًا مِنْ ‏ ‏الْبَيْتِ ‏ ‏إِلَّا الرُّكْنَيْنِ الْيَمَانِيَيْنِ فَإِنَّهُ كَانَ يَسْتَلِمُهُمَا وَيُخْبِرُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَفْعَلُهُ ‏","","",""],[5676,5676,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُجَّاجًا فَمَا أَحْلَلْنَا مِنْ شَيْءٍ حَتَّى أَحْلَلْنَا ‏ ‏يَوْمَ النَّحْرِ ‏","","",""],[5677,5677,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏قَالَ يَا رَسُولَ اللَّهِ إِنِّي أُرِيدُ أَنْ ‏ ‏أَتَصَدَّقَ ‏ ‏بِمَالِي ‏ ‏بِثَمْغٍ ‏ ‏قَالَ ‏ ‏احْبِسْ أَصْلَهُ ‏ ‏وَسَبِّلْ ‏ ‏ثَمَرَتَهُ ‏","","",""],[5678,5678,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏مَا صُمْتُ ‏ ‏عَرَفَةَ ‏ ‏قَطُّ وَلَا صَامَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا ‏ ‏أَبُو بَكْرٍ ‏ ‏وَلَا ‏ ‏عُمَرُ ‏","","",""],[5679,5679,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏قَالَ ‏ ‏جَلَسْتُ إِلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏وَمَعَهُ رَجُلٌ يُحَدِّثُهُ فَدَخَلْتُ مَعَهُمَا فَضَرَبَ بِيَدِهِ صَدْرِي وَقَالَ أَمَا عَلِمْتَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا تَنَاجَى اثْنَانِ فَلَا تَجْلِسْ إِلَيْهِمَا حَتَّى تَسْتَأْذِنَهُمَا ‏","","",""],[5680,5680,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُصَفِّرُ ‏ ‏لِحْيَتَهُ وَيَلْبَسُ النِّعَالَ ‏ ‏السِّبْتِيَّةَ ‏ ‏وَيَسْتَلِمُ ‏ ‏الرُّكْنَيْنِ ‏ ‏وَيُلَبِّي إِذَا ‏ ‏اسْتَوَتْ ‏ ‏بِهِ ‏ ‏رَاحِلَتُهُ ‏ ‏وَيُخْبِرُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَفْعَلُهُ ‏","","",""],[5681,5681,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ حَفْصٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ إِلَى ‏ ‏عُمَرَ ‏ ‏بِحُلَّةٍ ‏ ‏مِنْ حَرِيرٍ ‏ ‏أَوْ ‏ ‏سِيَرَاءَ ‏ ‏أَوْ نَحْوِ هَذَا ‏ ‏فَرَآهَا عَلَيْهِ فَقَالَ ‏ ‏إِنِّي لَمْ أُرْسِلْ بِهَا إِلَيْكَ لِتَلْبَسَهَا إِنَّمَا هِيَ ثِيَابُ مَنْ لَا ‏ ‏خَلَاقَ ‏ ‏لَهُ إِنَّمَا بَعَثْتُ بِهَا إِلَيْكَ لِتَسْتَنْفِعَ بِهَا ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ حَفْصٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ إِلَى ‏ ‏عُمَرَ ‏ ‏بِحُلَّةٍ ‏ ‏فَذَكَرَهُ ‏","","",""],[5682,5682,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏سِنَانُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏كُلَيْبِ بْنِ وَائِلٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏ذَكَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِتْنَةً ‏ ‏فَمَرَّ رَجُلٌ فَقَالَ يُقْتَلُ فِيهَا هَذَا ‏ ‏الْمُقَنَّعُ ‏ ‏يَوْمَئِذٍ ‏ ‏ظُلْمًا ‏ ‏قَالَ فَنَظَرْتُ فَإِذَا هُوَ ‏ ‏عُثْمَانُ بْنُ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏","","",""],[5683,5683,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ سُئِلَ عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏فَقَالَ ‏ ‏حَرَّمَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَأَتَيْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَقُلْتُ لَهُ سَأَلْتُ ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏فَقَالَ حَرَّمَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَدَقَ ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏قُلْتُ مَا ‏ ‏الْجَرُّ ‏ ‏قَالَ ‏ ‏كُلُّ شَيْءٍ مِنْ ‏ ‏مَدَرٍ ‏","","",""],[5684,5684,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏سَمِعْتُ ‏ ‏سَلَمَةَ بْنَ كُهَيْلٍ ‏ ‏يَذْكُرُ عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَأَعْلَمُ شَجَرَةً يُنْتَفَعُ بِهَا مِثْلَ الْمُؤْمِنِ هِيَ الَّتِي لَا يُنْفَضُ وَرَقُهَا قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏أَرَدْتُ أَنْ أَقُولَ هِيَ النَّخْلَةُ ‏ ‏فَفَرِقْتُ ‏ ‏مِنْ ‏ ‏عُمَرَ ‏ ‏ثُمَّ سَمِعْتُهُ بَعْدُ يَقُولُ هِيَ النَّخْلَةُ ‏","","",""],[5685,5685,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ هَذَا الْحَدِيثَ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ ‏ ‏وَحُسَيْنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُرَاهُ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ‏ ‏مَثَّلَ ‏ ‏بِذِي الرُّوحِ ثُمَّ لَمْ يَتُبْ ‏ ‏مَثَّلَ ‏ ‏اللَّهُ بِهِ يَوْمَ الْقِيَامَةِ ‏ ‏قَالَ ‏ ‏حُسَيْنٌ ‏ ‏مَنْ ‏ ‏مَثَّلَ ‏ ‏بِذِي رُوحٍ ‏","","",""],[5686,5686,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ الْبَطِينِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ خَلْفَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثَ مَرَّاتٍ فَقَرَأَ ‏ ‏السَّجْدَةَ ‏ ‏فِي ‏ ‏الْمَكْتُوبَةِ ‏","","",""],[5687,5687,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ هَذَا الْحَدِيثَ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ بْنُ عُتْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ خَالِدٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏عَنْ امْرَأَةٍ أَرَادَ أَنْ يَتَزَوَّجَهَا رَجُلٌ وَهُوَ خَارِجٌ مِنْ ‏ ‏مَكَّةَ ‏ ‏فَأَرَادَ أَنْ يَعْتَمِرَ أَوْ يَحُجَّ فَقَالَ ‏ ‏لَا تَزَوَّجْهَا وَأَنْتَ مُحْرِمٌ نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْهُ ‏","","",""],[5688,5688,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِامْرَأَةٍ يَوْمَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏مَقْتُولَةٍ فَقَالَ مَا كَانَتْ هَذِهِ تُقَاتِلُ ثُمَّ ‏ ‏نَهَى عَنْ قَتْلِ النِّسَاءِ وَالصِّبْيَانِ ‏","","",""],[5689,5689,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏وَابْنُ أَبِي بُكَيْرٍ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ التَّيْمِيِّ ‏ ‏وَإِبْرَاهِيمَ بْنِ مَيْسَرَةَ ‏ ‏أَنَّهُمَا سَمِعَا ‏ ‏طَاوُسًا ‏ ‏يَقُولُ ‏ ‏جَاءَ وَاللَّهِ رَجُلٌ إِلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏فَقَالَ ‏ ‏أَنَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏فَقَالَ نَعَمْ ‏ ‏وَزَادَهُمْ ‏ ‏إِبْرَاهِيمُ ‏ ‏الدُّبَّاءَ ‏ ‏قَالَ ‏ ‏ابْنُ أَبِي بُكَيْرٍ ‏ ‏قَالَ ‏ ‏إِبْرَاهِيمُ بْنُ مَيْسَرَةَ ‏ ‏فِي حَدِيثِهِ ‏ ‏وَالدُّبَّاءِ ‏","","",""],[5690,5690,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏وَيَحْيَى بْنِ وَثَّابٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ عَلَى هَذَا الْمِنْبَرِ ‏ ‏مَنْ أَتَى الْجُمُعَةَ فَلْيَغْتَسِلْ ‏","","",""],[5691,5691,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ الضَّبِّ فَقَالَ ‏ ‏لَا آكُلُهُ وَلَا أُحَرِّمُهُ ‏","","",""],[5692,5692,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏وَحَمْزَةَ ‏ ‏ابْنَيْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏حَدَّثَهُمَا ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الشُّؤْمُ فِي الْفَرَسِ وَالْمَرْأَةِ وَالدَّارِ ‏","","",""],[5693,5693,"","","‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ دُكَيْنٍ ‏ ‏حَدَّثَنَا ‏ ‏زَمْعَةُ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُلْدَغُ الْمُؤْمِنُ مِنْ جُحْرٍ مَرَّتَيْنِ ‏","","",""],[5694,5694,"","","‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ دُكَيْنٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي رَوَّادٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَسْتَلِمُ الرُّكْنَ ‏ ‏الْيَمَانِيَ وَالْأَسْوَدَ كُلَّ طَوَافِهِ وَلَا يَسْتَلِمُ الرُّكْنَيْنِ الْآخَرَيْنِ اللَّذَيْنِ يَلِيَانِ الْحَجَرَ ‏","","",""],[5695,5695,"","","‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ دُكَيْنٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏سَمِعْتُ ‏ ‏سَلَمَةَ بْنَ كُهَيْلٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالشَّمْسُ عَلَى ‏ ‏قُعَيْقِعَانَ ‏ ‏بَعْدَ الْعَصْرِ فَقَالَ ‏ ‏مَا أَعْمَارُكُمْ فِي أَعْمَارِ مَنْ مَضَى إِلَّا كَمَا بَقِيَ مِنْ النَّهَارِ فِيمَا مَضَى مِنْهُ ‏","","",""],[5696,5696,"","","‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ دُكَيْنٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏سَأَلَ ‏ ‏عُمَرُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ تُصِيبُنِي الْجَنَابَةُ مِنْ اللَّيْلِ ‏ ‏فَأَمَرَهُ أَنْ يَغْسِلَ ذَكَرَهُ وَيَتَوَضَّأَ وَيَرْقُدَ ‏","","",""],[5697,5697,"","","‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ دُكَيْنٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِكُلِّ غَادِرٍ ‏ ‏لِوَاءٌ ‏ ‏يَوْمَ الْقِيَامَةِ يُعْرَفُ بِهِ ‏","","",""],[5698,5698,"","","‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ دُكَيْنٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْلَمُ ‏ ‏سَالَمَهَا اللَّهُ ‏ ‏وَغِفَارٌ ‏ ‏غَفَرَ اللَّهُ لَهَا ‏ ‏وَعُصَيَّةُ ‏ ‏الَّذِينَ عَصَوْا اللَّهَ وَرَسُولَهُ ‏","","",""],[5699,5699,"","","‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ دُكَيْنٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ ‏ ‏رَجُلٌ ‏ ‏لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي أُخْدَعُ فِي الْبَيْعِ فَقَالَ ‏ ‏إِذَا بَايَعْتَ فَقُلْ لَا ‏ ‏خِلَابَةَ ‏ ‏فَكَانَ الرَّجُلُ يَقُولُهُ ‏","","",""],[5700,5700,"","","‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏اتَّخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَاتَمًا مِنْ ذَهَبٍ فَاتَّخَذَ النَّاسُ خَوَاتِيمَ مِنْ ذَهَبٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي اتَّخَذْتُ خَاتَمًا مِنْ ذَهَبٍ ‏ ‏فَنَبَذْتُهُ ‏ ‏وَقَالَ إِنِّي لَسْتُ أَلْبَسُهُ أَبَدًا ‏ ‏فَنَبَذَ ‏ ‏النَّاسُ خَوَاتِيمَهُمْ ‏","","",""],[5701,5701,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى رَجُلًا سَاقِطًا يَدَهُ فِي الصَّلَاةِ فَقَالَ ‏ ‏لَا تَجْلِسْ هَكَذَا إِنَّمَا هَذِهِ جِلْسَةُ الَّذِينَ يُعَذَّبُونَ ‏","","",""],[5702,5702,"","","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ حَمْزَةَ الْعُمَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اسْتَطَاعَ مِنْكُمْ أَنْ يَكُونَ مِثْلَ صَاحِبِ فَرَقِ ‏ ‏الْأَرُزِّ فَلْيَكُنْ مِثْلَهُ قَالُوا يَا رَسُولَ اللَّهِ وَمَا صَاحِبُ فَرَقِ الْأَرُزِّ قَالَ خَرَجَ ثَلَاثَةٌ فَغَيَّمَتْ عَلَيْهِمْ السَّمَاءُ فَدَخَلُوا غَارًا فَجَاءَتْ صَخْرَةٌ مِنْ أَعْلَى الْجَبَلِ حَتَّى طَبَّقَتْ الْبَابَ عَلَيْهِمْ فَعَالَجُوهَا فَلَمْ يَسْتَطِيعُوهَا فَقَالَ بَعْضُهُمْ لِبَعْضٍ لَقَدْ وَقَعْتُمْ فِي أَمْرٍ عَظِيمٍ فَلْيَدْعُ كُلُّ رَجُلٍ بِأَحْسَنِ مَا عَمِلَ لَعَلَّ اللَّهَ تَعَالَى أَنْ يُنْجِيَنَا مِنْ هَذَا فَقَالَ أَحَدُهُمْ اللَّهُمَّ إِنَّكَ تَعْلَمُ أَنَّهُ كَانَ لِي أَبَوَانِ شَيْخَانِ كَبِيرَانِ وَكُنْتُ أَحْلُبُ حِلَابَهُمَا فَأَجِيئُهُمَا وَقَدْ نَامَا فَكُنْتُ أَبِيتُ قَائِمًا وَحِلَابُهُمَا عَلَى يَدِي أَكْرَهُ أَنْ أَبْدَأَ بِأَحَدٍ قَبْلَهُمَا أَوْ أَنْ أُوقِظَهُمَا مِنْ نَوْمِهِمَا وَصِبْيَتِي ‏ ‏يَتَضَاغَوْنَ ‏ ‏حَوْلِي فَإِنْ كُنْتَ تَعْلَمُ أَنِّي إِنَّمَا فَعَلْتُهُ مِنْ خَشْيَتِكَ ‏ ‏فَافْرُجْ ‏ ‏عَنَّا قَالَ فَتَحَرَّكَتْ الصَّخْرَةُ قَالَ وَقَالَ الثَّانِي اللَّهُمَّ إِنَّكَ تَعْلَمُ أَنَّهُ كَانَتْ لِي ابْنَةُ عَمٍّ لَمْ يَكُنْ شَيْءٌ مِمَّا خَلَقْتَ أَحَبَّ إِلَيَّ مِنْهَا فَسُمْتُهَا نَفْسَهَا فَقَالَتْ لَا وَاللَّهِ دُونَ مِائَةِ دِينَارٍ فَجَمَعْتُهَا وَدَفَعْتُهَا إِلَيْهَا حَتَّى إِذَا جَلَسْتُ مِنْهَا مَجْلِسَ الرَّجُلِ فَقَالَتْ اتَّقِ اللَّهَ وَلَا تَفُضَّ الْخَاتَمَ إِلَّا بِحَقِّهِ فَقُمْتُ عَنْهَا فَإِنْ كُنْتَ تَعْلَمُ أَنَّمَا فَعَلْتُهُ مِنْ خَشْيَتِكَ فَافْرُجْ عَنَّا قَالَ فَزَالَتْ الصَّخْرَةُ حَتَّى بَدَتْ السَّمَاءُ وَقَالَ الثَّالِثُ اللَّهُمَّ إِنَّكَ تَعْلَمُ أَنِّي كُنْتُ اسْتَأْجَرْتُ أَجِيرًا بِفَرَقٍ مِنْ أَرُزٍّ فَلَمَّا أَمْسَى عَرَضْتُ عَلَيْهِ حَقَّهُ فَأَبَى أَنْ يَأْخُذَهُ وَذَهَبَ وَتَرَكَنِي فَتَحَرَّجْتُ مِنْهُ وَثَمَّرْتُهُ لَهُ وَأَصْلَحْتُهُ حَتَّى اشْتَرَيْتُ مِنْهُ بَقَرًا وَرَاعِيَهَا فَلَقِيَنِي بَعْدَ حِينٍ فَقَالَ اتَّقِ اللَّهَ وَأَعْطِنِي أَجْرِي وَلَا تَظْلِمْنِي فَقُلْتُ انْطَلِقْ إِلَى ذَلِكَ الْبَقَرِ وَرَاعِيهَا فَخُذْهَا فَقَالَ اتَّقِ اللَّهَ وَلَا تَسْخَرْ بِي فَقُلْتُ إِنِّي لَسْتُ أَسْخَرُ بِكَ فَانْطَلَقَ فَاسْتَاقَ ذَلِكَ فَإِنْ كُنْتَ تَعْلَمُ أَنِّي إِنَّمَا فَعَلْتُهُ ‏ ‏ابْتِغَاءَ ‏ ‏مَرْضَاتِكَ خَشْيَةً مِنْكَ فَافْرُجْ عَنَّا فَتَدَحْرَجَتْ الصَّخْرَةُ فَخَرَجُوا يَمْشُونَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَمَا ثَلَاثَةُ ‏ ‏رَهْطٍ ‏ ‏يَتَمَاشَوْنَ أَخَذَهُمْ الْمَطَرُ ‏ ‏فَأَوَوْا ‏ ‏إِلَى غَارٍ فِي جَبَلٍ فَبَيْنَمَا هُمْ فِيهِ ‏ ‏حَطَّتْ ‏ ‏صَخْرَةٌ مِنْ الْجَبَلِ فَأَطْبَقَتْ عَلَيْهِمْ فَذَكَرَ الْحَدِيثَ مِثْلَ مَعْنَاهُ ‏","","",""],[5703,5703,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏سَمِعْتُ ‏ ‏نَافِعًا ‏ ‏يَقُولُ قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَتْلِ الْكِلَابِ فَكُنْتُ فِيمَنْ بَعَثَ فَقَتَلْنَا الْكِلَابَ حَتَّى وَجَدْنَا امْرَأَةً قَدِمَتْ مِنْ ‏ ‏الْبَادِيَةِ ‏ ‏فَقَتَلْنَا كَلْبًا لَهَا ‏","","",""],[5704,5704,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏حَدَّثَنِي ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏أَنَّهُ حَدَّثَهُ عَنْ رُؤْيَا رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي وَبَاءِ ‏ ‏الْمَدِينَةِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ رَأَيْتُ امْرَأَةً سَوْدَاءَ ثَائِرَةَ الرَّأْسِ خَرَجَتْ مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏حَتَّى أَقَامَتْ ‏ ‏بِمَهْيَعَةَ ‏ ‏وَهِيَ ‏ ‏الْجُحْفَةُ ‏ ‏فَأَوَّلَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ وَبَاءَ ‏ ‏الْمَدِينَةِ ‏ ‏نُقِلَ إِلَى ‏ ‏الْجُحْفَةِ ‏","","",""],[5705,5705,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا يَحْكِي عَنْ رَبِّهِ تَبَارَكَ وَتَعَالَى قَالَ ‏ ‏أَيُّمَا عَبْدٍ مِنْ عِبَادِي خَرَجَ مُجَاهِدًا فِي سَبِيلِي ‏ ‏ابْتِغَاءَ ‏ ‏مَرْضَاتِي ضَمِنْتُ لَهُ أَنْ أُرْجِعَهُ بِمَا ‏ ‏أَصَابَ ‏ ‏مِنْ أَجْرٍ وَغَنِيمَةٍ وَإِنْ قَبَضْتُهُ أَنْ أَغْفِرَ لَهُ وَأَرْحَمَهُ وَأُدْخِلَهُ الْجَنَّةَ ‏","","",""],[5706,5706,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ سَلْمَانَ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏حَفِظْتُ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَشْرَ صَلَوَاتٍ رَكْعَتَيْنِ قَبْلَ صَلَاةِ الصُّبْحِ وَرَكْعَتَيْنِ قَبْلَ صَلَاةِ الظُّهْرِ وَرَكْعَتَيْنِ بَعْدَ صَلَاةِ الظُّهْرِ وَرَكْعَتَيْنِ بَعْدَ صَلَاةِ الْمَغْرِبِ وَرَكْعَتَيْنِ بَعْدَ الْعِشَاءِ ‏","","",""],[5707,5707,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُسْلِمِ بْنِ مِهْرَانَ ‏ ‏مَوْلًى ‏ ‏لِقُرَيْشٍ ‏ ‏سَمِعْتُ ‏ ‏جَدِّي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏لَا يَنَامُ إِلَّا وَالسِّوَاكُ عِنْدَهُ فَإِذَا اسْتَيْقَظَ بَدَأَ بِالسِّوَاكِ ‏","","",""],[5708,5708,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُسْلِمِ بْنِ مِهْرَانَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَدَّهُ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَحِمَ اللَّهُ امْرَأً صَلَّى قَبْلَ الْعَصْرِ أَرْبَعًا ‏","","",""],[5709,5709,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏انْتَهَيْتُ إِلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏وَقَدْ حَدَّثَ الْحَدِيثَ فَقُلْتُ مَا ‏ ‏حَدَّثَ ‏ ‏فَقَالُوا ‏ ‏قَالَ ‏ ‏حَدَّثَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏غِفَارٌ ‏ ‏غَفَرَ اللَّهُ لَهَا ‏ ‏وَأَسْلَمُ ‏ ‏سَالَمَهَا اللَّهُ ‏","","",""],[5710,5710,"","","‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْوَاحِدِ الْبُنَانِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏فَجَاءَهُ رَجُلٌ فَقَالَ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏إِنِّي ‏ ‏أَشْتَرِي هَذِهِ ‏ ‏الْحِيطَانَ ‏ ‏تَكُونُ فِيهَا الْأَعْنَابُ فَلَا نَسْتَطِيعُ أَنْ نَبِيعَهَا كُلَّهَا عِنَبًا حَتَّى نَعْصِرَهُ قَالَ فَعَنْ ثَمَنِ الْخَمْرِ تَسْأَلُنِي سَأُحَدِّثُكَ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُنَّا جُلُوسًا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ رَفَعَ رَأْسَهُ إِلَى السَّمَاءِ ثُمَّ ‏ ‏أَكَبَّ ‏ ‏وَنَكَتَ فِي الْأَرْضِ وَقَالَ ‏ ‏الْوَيْلُ ‏ ‏لِبَنِي إِسْرَائِيلَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا نَبِيَّ اللَّهِ لَقَدْ أَفْزَعَنَا قَوْلُكَ ‏ ‏لِبَنِي إِسْرَائِيلَ ‏ ‏فَقَالَ لَيْسَ عَلَيْكُمْ مِنْ ذَلِكَ ‏ ‏بَأْسٌ ‏ ‏إِنَّهُمْ لَمَّا حُرِّمَتْ عَلَيْهِمْ الشُّحُومُ ‏ ‏فَتَوَاطَئُوهُ ‏ ‏فَيَبِيعُونَهُ فَيَأْكُلُونَ ثَمَنَهُ وَكَذَلِكَ ثَمَنُ الْخَمْرِ عَلَيْكُمْ حَرَامٌ ‏","","",""],[5711,5711,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ يَعْنِي الْمُعَلِّمَ ‏ ‏عَنْ ‏ ‏ابْنِ بُرَيْدَةَ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ إِذَا ‏ ‏تَبَوَّأَ ‏ ‏مَضْجَعَهُ قَالَ ‏ ‏الْحَمْدُ لِلَّهِ الَّذِي كَفَانِي وَآوَانِي وَأَطْعَمَنِي وَسَقَانِي وَالَّذِي مَنَّ عَلَيَّ وَأَفْضَلَ وَالَّذِي أَعْطَانِي فَأَجْزَلَ الْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ اللَّهُمَّ رَبَّ كُلِّ شَيْءٍ وَمَلِكَ كُلِّ شَيْءٍ وَإِلَهَ كُلِّ شَيْءٍ وَلَكَ كُلُّ شَيْءٍ أَعُوذُ بِكَ مِنْ النَّارِ ‏","","",""],[5712,5712,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏صَخْرٌ يَعْنِي ابْنَ جُوَيْرِيَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَزَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالنَّاسِ عَامَ ‏ ‏تَبُوكَ ‏ ‏نَزَلَ بِهِمْ ‏ ‏الْحِجْرَ ‏ ‏عِنْدَ بُيُوتِ ‏ ‏ثَمُودَ ‏ ‏فَاسْتَسْقَى النَّاسُ مِنْ الْآبَارِ الَّتِي كَانَ يَشْرَبُ مِنْهَا ‏ ‏ثَمُودُ ‏ ‏فَعَجَنُوا مِنْهَا وَنَصَبُوا الْقُدُورَ بِاللَّحْمِ ‏ ‏فَأَمَرَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَهَرَاقُوا ‏ ‏الْقُدُورَ وَعَلَفُوا الْعَجِينَ الْإِبِلَ ثُمَّ ‏ ‏ارْتَحَلَ ‏ ‏بِهِمْ حَتَّى نَزَلَ بِهِمْ عَلَى الْبِئْرِ الَّتِي كَانَتْ تَشْرَبُ مِنْهَا النَّاقَةُ وَنَهَاهُمْ أَنْ يَدْخُلُوا عَلَى الْقَوْمِ الَّذِينَ عُذِّبُوا قَالَ إِنِّي أَخْشَى أَنْ يُصِيبَكُمْ مِثْلُ مَا أَصَابَهُمْ فَلَا تَدْخُلُوا عَلَيْهِمْ ‏","","",""],[5713,5713,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مِهْرَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّهُ ‏ ‏كَانَ عِنْدَهُ رَجُلٌ مِنْ أَهْلِ ‏ ‏الْكُوفَةِ ‏ ‏فَجَعَلَ يُحَدِّثُهُ عَنْ ‏ ‏الْمُخْتَارِ ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏إِنْ كَانَ كَمَا تَقُولُ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ بَيْنَ يَدَيْ السَّاعَةِ ثَلَاثِينَ كَذَّابًا ‏","","",""],[5714,5714,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِرَجُلٍ فَعَلْتَ كَذَا وَكَذَا فَقَالَ لَا وَالَّذِي لَا إِلَهَ إِلَّا هُوَ يَا رَسُولَ اللَّهِ مَا فَعَلْتُ قَالَ ‏ ‏بَلَى قَدْ فَعَلْتَ وَلَكِنْ غُفِرَ لَكَ بِالْإِخْلَاصِ ‏","","",""],[5715,5715,"","","‏ ‏حَدَّثَنَا ‏ ‏أَزْهَرُ بْنُ سَعْدٍ أَبُو بَكْرٍ السَّمَّانُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اللَّهُمَّ بَارِكْ لَنَا فِي ‏ ‏شَامِنَا ‏ ‏اللَّهُمَّ بَارِكْ لَنَا فِي ‏ ‏يَمَنِنَا ‏ ‏قَالُوا وَفِي ‏ ‏نَجْدِنَا ‏ ‏قَالَ اللَّهُمَّ بَارِكْ لَنَا فِي ‏ ‏شَامِنَا ‏ ‏اللَّهُمَّ بَارِكْ لَنَا فِي ‏ ‏يَمَنِنَا ‏ ‏قَالُوا وَفِي ‏ ‏نَجْدِنَا ‏ ‏قَالَ هُنَالِكَ الزَّلَازِلُ وَالْفِتَنُ مِنْهَا ‏ ‏أَوْ قَالَ بِهَا يَطْلُعُ قَرْنُ الشَّيْطَانِ ‏","","",""],[5716,5716,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حَنْظَلَةَ ‏ ‏يَذْكُرُ عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْفِطْرَةِ حَلْقُ ‏ ‏الْعَانَةِ ‏ ‏وَتَقْلِيمُ الْأَظْفَارِ وَقَصُّ الشَّارِبِ ‏ ‏وَقَالَ ‏ ‏إِسْحَاقُ ‏ ‏مَرَّةً وَقَصُّ الشَّوَارِبِ ‏","","",""],[5717,5717,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ الْمَدَائِنِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏مُبَارَكُ بْنُ فَضَالَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏حَدَّثَهُ قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْقَزَعِ ‏","","",""],[5718,5718,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏حَدَّثَنِي ‏ ‏حُسَيْنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُبَارَكُ بْنُ فَضَالَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ دِينَارٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏حَدَّثَهُ قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْقَزَعِ ‏","","",""],[5719,5719,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏حَدَّثَنِي ‏ ‏حَنْظَلَةُ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّهُ ‏ ‏كَانَ يَكْرَهُ الْعَلَمَ فِي الصُّورَةِ وَقَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ضَرْبِ الْوَجْهِ ‏","","",""],[5720,5720,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مِنْ ‏ ‏الْحِنْطَةِ ‏ ‏خَمْرٌ وَمِنْ التَّمْرِ خَمْرٌ وَمِنْ الشَّعِيرِ خَمْرٌ وَمِنْ الزَّبِيبِ خَمْرٌ وَمِنْ الْعَسَلِ خَمْرٌ ‏","","",""],[5721,5721,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَارَ أَهْلُ الْجَنَّةِ فِي الْجَنَّةِ وَأَهْلُ النَّارِ فِي النَّارِ جِيءَ بِالْمَوْتِ حَتَّى يُوقَفَ بَيْنَ الْجَنَّةِ وَالنَّارِ ثُمَّ يُذْبَحُ ثُمَّ يُنَادِي مُنَادٍ يَا أَهْلَ الْجَنَّةِ خُلُودٌ لَا مَوْتَ يَا أَهْلَ النَّارِ خُلُودٌ لَا مَوْتَ فَازْدَادَ أَهْلُ الْجَنَّةِ فَرَحًا إِلَى فَرَحِهِمْ وَازْدَادَ أَهْلُ النَّارِ حُزْنًا إِلَى حُزْنِهِمْ ‏","","",""],[5722,5722,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْحَارِثِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏النَّذْرَ ‏ ‏لَا يُقَدِّمُ شَيْئًا وَلَا يُؤَخِّرُهُ وَإِنَّمَا يُسْتَخْرَجُ ‏ ‏بِالنَّذْرِ ‏ ‏مِنْ الْبَخِيلِ ‏","","",""],[5723,5723,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ بْنُ الْقَاسِمِ الْحَنَفِيُّ يَمَامِيٌّ ‏ ‏سَمِعْتُ ‏ ‏عِكْرِمَةَ بْنَ خَالِدٍ الْمَخْزُومِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَعَظَّمَ فِي نَفْسِهِ أَوْ اخْتَالَ فِي مِشْيَتِهِ لَقِيَ اللَّهَ وَهُوَ عَلَيْهِ غَضْبَانُ ‏","","",""],[5724,5724,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ الْقَاسِمِ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ الشَّمْسَ وَالْقَمَرَ لَا يَنْكَسِفَانِ لِمَوْتِ أَحَدٍ وَلَا لِحَيَاتِهِ وَلَكِنَّهُمَا آيَةٌ مِنْ آيَاتِ اللَّهِ فَإِذَا رَأَيْتُمُوهُمَا فَصَلُّوا ‏","","",""],[5725,5725,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْعُو عَلَى رِجَالٍ مِنْ الْمُشْرِكِينَ ‏ ‏يُسَمِّيهِمْ بِأَسْمَائِهِمْ حَتَّى أَنْزَلَ اللَّهُ ‏ { ‏لَيْسَ لَكَ مِنْ الْأَمْرِ شَيْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَالِمُونَ ‏} ‏فَتَرَكَ ذَلِكَ ‏","","",""],[5726,5726,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏قَالَ قَالَ ‏ ‏حَيْوَةُ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو عُثْمَانَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ دِينَارٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَفْرَى الْفِرَى ‏ ‏مَنْ ‏ ‏ادَّعَى ‏ ‏إِلَى غَيْرِ أَبِيهِ ‏ ‏وَأَفْرَى الْفِرَى ‏ ‏مَنْ أَرَى عَيْنَيْهِ فِي النَّوْمِ مَا لَمْ تَرَيَا وَمَنْ غَيَّرَ ‏ ‏تُخُومَ ‏ ‏الْأَرْضِ ‏","","",""],[5727,5727,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي إِسْحَاقُ بْنُ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ قَيْسِ بْنِ مَخْرَمَةَ ‏ ‏قَالَ ‏ ‏أَقْبَلْتُ مِنْ مَسْجِدِ ‏ ‏بَنِي عَمْرِو بْنِ عَوْفٍ ‏ ‏بِقُبَاءَ ‏ ‏عَلَى بَغْلَةٍ لِي قَدْ صَلَّيْتُ فِيهِ فَلَقِيتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏مَاشِيًا فَلَمَّا رَأَيْتُهُ نَزَلْتُ عَنْ بَغْلَتِي ثُمَّ قُلْتُ ارْكَبْ أَيْ عَمِّ قَالَ أَيْ ابْنَ أَخِي لَوْ أَرَدْتُ أَنْ أَرْكَبَ الدَّوَابَّ ‏ ‏لَرَكِبْتُ ‏ ‏وَلَكِنِّي ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْشِي إِلَى هَذَا الْمَسْجِدِ حَتَّى يَأْتِيَ فَيُصَلِّيَ فِيهِ فَأَنَا أُحِبُّ أَنْ أَمْشِيَ إِلَيْهِ كَمَا رَأَيْتُهُ يَمْشِي قَالَ فَأَبَى أَنْ يَرْكَبَ وَمَضَى عَلَى وَجْهِهِ ‏","","",""],[5728,5728,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏إِذَا جَلَسَ فِي الصَّلَاةِ وَضَعَ يَدَيْهِ عَلَى رُكْبَتَيْهِ وَأَشَارَ بِإِصْبَعِهِ وَأَتْبَعَهَا بَصَرَهُ ثُمَّ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَهِيَ أَشَدُّ عَلَى الشَّيْطَانِ مِنْ الْحَدِيدِ ‏ ‏يَعْنِي السَّبَّابَةَ ‏","","",""],[5729,5729,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏قَطَنِ بْنِ وَهْبِ بْنِ عُوَيْمِرٍ ‏ ‏عَنْ ‏ ‏يُحَنَّسَ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَصْبِرُ أَحَدٌ عَلَى ‏ ‏لَأْوَائِهَا ‏ ‏وَشِدَّتِهَا ‏ ‏إِلَّا كُنْتُ لَهُ شَهِيدًا ‏ ‏أَوْ شَفِيعًا ‏ ‏يَوْمَ الْقِيَامَةِ ‏","","",""],[5730,5730,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏الْحُسَيْنُ يَعْنِي الْمُعَلِّمَ ‏ ‏قَالَ قَالَ لِي ‏ ‏يَحْيَى ‏ ‏حَدَّثَنِي ‏ ‏أَبُو قِلَابَةَ ‏ ‏حَدَّثَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ لَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَتَخْرُجُ نَارٌ قَبْلَ يَوْمِ الْقِيَامَةِ مِنْ بَحْرِ ‏ ‏حَضْرَمَوْتَ ‏ ‏تَحْشُرُ النَّاسَ قَالُوا فَمَا تَأْمُرُنَا يَا رَسُولَ اللَّهِ قَالَ عَلَيْكُمْ ‏ ‏بِالشَّامِ ‏","","",""],[5731,5731,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّهُ قَالَ قَامَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ مَاذَا تَأْمُرُنَا أَنْ نَلْبَسَ مِنْ الثِّيَابِ فِي الْإِحْرَامِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَلْبَسُوا الْقُمُصَ وَلَا السَّرَاوِيلَاتِ وَلَا الْعَمَائِمَ وَلَا ‏ ‏الْبَرَانِسَ ‏ ‏وَلَا ‏ ‏الْخِفَافَ ‏ ‏إِلَّا أَنْ يَكُونَ أَحَدٌ لَيْسَتْ لَهُ نَعْلَانِ فَلْيَلْبَسْ ‏ ‏الْخُفَّيْنِ ‏ ‏مَا أَسْفَلَ مِنْ الْكَعْبَيْنِ وَلَا تَلْبَسُوا شَيْئًا مِنْ الثِّيَابِ مَسَّهُ ‏ ‏الْوَرْسُ ‏ ‏وَلَا الزَّعْفَرَانُ وَلَا ‏ ‏تَنْتَقِبْ ‏ ‏الْمَرْأَةُ الْحَرَامُ وَلَا تَلْبَسْ الْقُفَّازَيْنِ ‏","","",""],[5732,5732,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ ‏ ‏كَانَ ‏ ‏يُنِيخُ ‏ ‏بِالْبَطْحَاءِ ‏ ‏الَّتِي ‏ ‏بِذِي الْحُلَيْفَةِ ‏ ‏الَّتِي كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُنِيخُ ‏ ‏بِهَا وَيُصَلِّي بِهَا ‏","","",""],[5733,5733,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّهُ قَالَ ‏ ‏حَلَقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَحَلَقَ طَائِفَةٌ مِنْ أَصْحَابِهِ وَقَصَّرَ بَعْضُهُمْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَحِمَ اللَّهُ الْمُحَلِّقِينَ مَرَّةً ‏ ‏أَوْ مَرَّتَيْنِ ‏ ‏ثُمَّ قَالَ وَالْمُقَصِّرِينَ ‏","","",""],[5734,5734,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا تَبَايَعَ الرَّجُلَانِ فَكُلُّ وَاحِدٍ مِنْهُمَا ‏ ‏بِالْخِيَارِ ‏ ‏مَا لَمْ يَتَفَرَّقَا فَكَانَا جَمِيعًا وَيُخَيِّرُ أَحَدُهُمَا الْآخَرَ فَإِنْ ‏ ‏خَيَّرَ ‏ ‏أَحَدُهُمَا الْآخَرَ فَتَبَايَعَا عَلَى ذَلِكَ وَجَبَ الْبَيْعُ وَإِنْ تَفَرَّقَا بَعْدَ أَنْ تَبَايَعَا وَلَمْ يَتْرُكْ وَاحِدٌ مِنْهُمَا الْبَيْعَ فَقَدْ وَجَبَ الْبَيْعُ ‏","","",""],[5735,5735,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اصْطَنَعَ خَاتَمًا مِنْ ذَهَبٍ وَكَانَ يَجْعَلُ فَصَّهُ فِي بَاطِنِ كَفِّهِ إِذَا لَبِسَهُ فَصَنَعَ النَّاسُ ثُمَّ إِنَّهُ جَلَسَ عَلَى الْمِنْبَرِ فَنَزَعَهُ فَقَالَ ‏ ‏إِنِّي كُنْتُ أَلْبَسُ هَذَا الْخَاتَمَ وَأَجْعَلُ فَصَّهُ مِنْ دَاخِلٍ فَرَمَى بِهِ ثُمَّ قَالَ وَاللَّهِ لَا أَلْبَسُهُ أَبَدًا ‏ ‏فَنَبَذَ ‏ ‏النَّاسُ خَوَاتِيمَهُمْ ‏","","",""],[5736,5736,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى فَإِذَا خِفْتَ الصُّبْحَ فَأَوْتِرْ بِوَاحِدَةٍ وَاجْعَلْ آخِرَ صَلَاتِكَ ‏ ‏وِتْرًا ‏","","",""],[5737,5737,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنَا ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الرُّؤْيَا الصَّالِحَةُ جُزْءٌ مِنْ سَبْعِينَ جُزْءًا مِنْ النُّبُوَّةِ ‏","","",""],[5738,5738,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏جِسْرٌ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيطٌ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَحْسَسْتُمْ بِالْحُمَّى فَأَطْفِئُوهَا بِالْمَاءِ الْبَارِدِ ‏","","",""],[5739,5739,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ يَعْنِي شَيْبَانَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏فَقَالَ يَا ‏ ‏ابْنَ عُمَرَ ‏ ‏إِنِّي سَائِلُكَ عَنْ شَيْءٍ تُحَدِّثُنِي بِهِ قَالَ نَعَمْ فَذَكَرَ ‏ ‏عُثْمَانَ ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏أَمَّا تَغَيُّبُهُ عَنْ ‏ ‏بَدْرٍ ‏ ‏فَإِنَّهُ كَانَتْ تَحْتَهُ ابْنَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَتْ مَرِيضَةً فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لَكَ أَجْرَ رَجُلٍ شَهِدَ ‏ ‏بَدْرًا ‏ ‏وَسَهْمَهُ ‏ ‏وَأَمَّا تَغَيُّبُهُ عَنْ بَيْعَةِ الرِّضْوَانِ فَإِنَّهُ لَوْ كَانَ أَحَدٌ أَعَزَّ بِبَطْنِ ‏ ‏مَكَّةَ ‏ ‏مِنْ ‏ ‏عُثْمَانَ ‏ ‏لَبَعَثَهُ فَبَعَثَ ‏ ‏عُثْمَانَ ‏ ‏وَكَانَتْ بَيْعَةُ الرِّضْوَانِ بَعْدَ مَا ذَهَبَ ‏ ‏عُثْمَانُ ‏ ‏إِلَى ‏ ‏مَكَّةَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ الْيُمْنَى هَذِهِ يَدُ ‏ ‏عُثْمَانَ ‏ ‏فَضَرَبَ بِيَدِهِ الْأُخْرَى عَلَيْهَا فَقَالَ هَذِهِ ‏ ‏لِعُثْمَانَ ‏ ‏فَقَالَ لَهُ ‏ ‏ابْنُ عُمَرَ ‏ ‏اذْهَبْ بِهَذِهِ الْآنَ مَعَكَ ‏","","",""],[5740,5740,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَيْثَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏وَعَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏النَّقِيرِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَالدُّبَّاءِ ‏","","",""],[5741,5741,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَيْثَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ جُمْهَانَ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏أَوْ قَالَ لَهُ غَيْرِي ‏ ‏مَا لِي أَرَاكَ تَمْشِي وَالنَّاسُ ‏ ‏يَسْعَوْنَ ‏ ‏فَقَالَ ‏ ‏إِنْ أَمْشِ فَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْشِي وَإِنْ ‏ ‏أَسْعَى ‏ ‏فَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْعَى ‏ ‏وَأَنَا شَيْخٌ كَبِيرٌ ‏","","",""],[5742,5742,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ يَعْنِي ابْنَ مُحَمَّدِ بْنِ زَيْدِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ يَعْلَمُ النَّاسُ مَا فِي الْوَحْدَةِ مَا أَعْلَمُ لَمْ يَسِرْ رَاكِبٌ بِلَيْلٍ وَحْدَهُ أَبَدًا ‏","","",""],[5743,5743,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ بُنِيَ الْإِسْلَامُ عَلَى خَمْسٍ ‏ ‏شَهَادَةِ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ وَإِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ وَحَجِّ ‏ ‏الْبَيْتِ ‏ ‏وَصَوْمِ رَمَضَانَ ‏","","",""],[5744,5744,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏صَدَرْتُ ‏ ‏مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏يَوْمَ ‏ ‏الصَّدَرِ ‏ ‏فَمَرَّتْ بِنَا ‏ ‏رُفْقَةٌ ‏ ‏يَمَانِيَةٌ وَرِحَالُهُمْ ‏ ‏الْأُدُمُ ‏ ‏وَخُطُمُ ‏ ‏إِبِلِهِمْ ‏ ‏الْخُزُمُ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏مَنْ أَحَبَّ أَنْ يَنْظُرَ إِلَى أَشْبَهِ رُفْقَةٍ وَرَدَتْ الْحَجَّ الْعَامَ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابِهِ إِذْ قَدِمُوا فِي حَجَّةِ الْوَدَاعِ فَلْيَنْظُرْ إِلَى هَذِهِ الرُّفْقَةِ ‏","","",""],[5745,5745,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏وَإِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏وَقَالَ ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَمْ أَرَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ مِنْ ‏ ‏الْبَيْتِ ‏ ‏إِلَّا الرُّكْنَيْنِ الْيَمَانِيَيْنِ ‏","","",""],[5746,5746,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏نَتَلَقَّى الْحَاجَّ فَنُسَلِّمُ عَلَيْهِمْ قَبْلَ أَنْ ‏ ‏يَتَدَنَّسُوا ‏","","",""],[5747,5747,"","","‏ ‏حَدَّثَنِي ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏وَهَاشِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَيْتَ ‏ ‏وَأُسَامَةُ بْنُ زَيْدٍ ‏ ‏وَبِلَالٌ ‏ ‏وَعُثْمَانُ بْنُ طَلْحَةَ الْحَجَبِيُّ ‏ ‏فَأَغْلَقُوا عَلَيْهِمْ فَلَمَّا فَتَحُوا كُنْتُ أَوَّلَ مَنْ ‏ ‏وَلَجَ ‏ ‏فَلَقِيتُ ‏ ‏بِلَالًا ‏ ‏فَسَأَلْتُهُ هَلْ صَلَّى فِيهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ بَيْنَ الْعَمُودَيْنِ الْيَمَانِيَيْنِ ‏ ‏قَالَ ‏ ‏هَاشِمٌ ‏ ‏صَلَّى بَيْنَ الْعَمُودَيْنِ ‏","","",""],[5748,5748,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنِي ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏وَيُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ وَهُوَ عَلَى الْمِنْبَرِ ‏ ‏مَنْ جَاءَ مِنْكُمْ الْجُمُعَةَ فَلْيَغْتَسِلْ ‏","","",""],[5749,5749,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُهِلُّ مُلَبِّدًا يَقُولُ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لَا شَرِيكَ لَكَ لَا يَزِيدُ عَلَى هَؤُلَاءِ الْكَلِمَاتِ ‏","","",""],[5750,5750,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَارَ أَهْلُ الْجَنَّةِ إِلَى ‏ ‏الْجَنَّةِ وَأَهْلُ النَّارِ إِلَى النَّارِ جِيءَ بِالْمَوْتِ حَتَّى يُجْعَلَ بَيْنَ الْجَنَّةِ وَالنَّارِ ثُمَّ يُذْبَحُ ثُمَّ يُنَادِي مُنَادٍ يَا أَهْلَ الْجَنَّةِ لَا مَوْتَ يَا أَهْلَ النَّارِ لَا مَوْتَ فَيَزْدَادُ أَهْلُ الْجَنَّةِ فَرَحًا إِلَى فَرَحِهِمْ وَيَزْدَادُ أَهْلُ النَّارِ حُزْنًا إِلَى حُزْنِهِمْ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عُمَرَ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَارَ أَهْلُ الْجَنَّةِ إِلَى الْجَنَّةِ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[5751,5751,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعَيْبُ بْنُ أَبِي حَمْزَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اجْتَمَعَ ثَلَاثَةٌ فَلَا يَتَنَاجَى اثْنَانِ دُونَ الثَّالِثِ وَلَا يُقِيمَنَّ أَحَدُكُمْ أَخَاهُ مِنْ مَجْلِسِهِ ثُمَّ يَجْلِسُ فِيهِ ‏","","",""],[5752,5752,"","","‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ شُعَيْبِ بْنِ أَبِي حَمْزَةَ ‏ ‏أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏فَذَكَرَ حَدِيثًا ‏ ‏وَقَالَ ‏ ‏سَالِمٌ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَائِمًا عَلَى الْمِنْبَرِ يَقُولُ ‏ ‏اقْتُلُوا الْحَيَّاتِ وَاقْتُلُوا ذَا ‏ ‏الطُّفْيَتَيْنِ ‏ ‏وَالْأَبْتَرَ ‏ ‏فَإِنَّهُمَا ‏ ‏يَلْتَمِسَانِ ‏ ‏الْبَصَرَ وَيُسْقِطَانِ ‏ ‏الْحَبَلَ ‏","","",""],[5753,5753,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّهُ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏كُلُّكُمْ رَاعٍ وَمَسْئُولٌ عَنْ رَعِيَّتِهِ الْإِمَامُ رَاعٍ وَهُوَ مَسْئُولٌ عَنْ رَعِيَّتِهِ وَالرَّجُلُ فِي أَهْلِهِ رَاعٍ وَهُوَ مَسْئُولٌ عَنْ رَعِيَّتِهِ وَالْمَرْأَةُ رَاعِيَةٌ فِي بَيْتِ زَوْجِهَا وَهِيَ مَسْئُولَةٌ عَنْ رَعِيَّتِهَا وَالْخَادِمُ فِي مَالِ سَيِّدِهِ رَاعٍ وَهُوَ مَسْئُولٌ عَنْ رَعِيَّتِهِ قَالَ سَمِعْتُ هَؤُلَاءِ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَحْسَبُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَالرَّجُلُ فِي مَالِ أَبِيهِ رَاعٍ وَهُوَ مَسْئُولٌ عَنْ رَعِيَّتِهِ ‏ ‏فَكُلُّكُمْ رَاعٍ وَكُلُّكُمْ مَسْئُولٌ عَنْ رَعِيَّتِهِ ‏","","",""],[5754,5754,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏عُمَرَ ‏ ‏يَقُولُ ‏ ‏مَنْ ‏ ‏ضَفَرَ ‏ ‏فَلْيَحْلِقْ وَلَا تَشَبَّهُوا ‏ ‏بِالتَّلْبِيدِ ‏ ‏وَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَقُولُ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُلَبِّدًا ‏","","",""],[5755,5755,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنَا ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏وَأَبُو بَكْرِ بْنُ أَبِي حَثْمَةَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏صَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الْعِشَاءِ فِي آخِرِ حَيَاتِهِ فَلَمَّا قَامَ قَالَ ‏ ‏أَرَأَيْتَكُمْ لَيْلَتَكُمْ هَذِهِ فَإِنَّ رَأْسَ مِائَةِ سَنَةٍ مِنْهَا لَا ‏ ‏يَبْقَى مِمَّنْ هُوَ الْيَوْمَ عَلَى ظَهْرِ الْأَرْضِ أَحَدٌ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَوَهَلَ ‏ ‏النَّاسُ فِي مَقَالَةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تِلْكَ إِلَى مَا يُحَدِّثُونَ مِنْ هَذِهِ الْأَحَادِيثِ عَنْ مِائَةِ سَنَةٍ فَإِنَّمَا قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يَبْقَى مِمَّنْ هُوَ الْيَوْمَ عَلَى ظَهْرِ الْأَرْضِ أَحَدٌ يُرِيدُ بِذَلِكَ أَنَّهُ ‏ ‏يَنْخَرِمُ ‏ ‏ذَلِكَ ‏ ‏الْقَرْنُ ‏","","",""],[5756,5756,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ قَائِمٌ عَلَى الْمِنْبَرِ يَقُولُ ‏ ‏أَلَا إِنَّ بَقَاءَكُمْ فِيمَا ‏ ‏سَلَفَ ‏ ‏قَبْلَكُمْ مِنْ الْأُمَمِ كَمَا بَيْنَ صَلَاةِ الْعَصْرِ إِلَى غُرُوبِ الشَّمْسِ أُعْطِيَ أَهْلُ التَّوْرَاةِ التَّوْرَاةَ فَعَمِلُوا بِهَا حَتَّى إِذَا انْتَصَفَ النَّهَارُ عَجَزُوا فَأُعْطُوا ‏ ‏قِيرَاطًا ‏ ‏قِيرَاطًا ‏ ‏وَأُعْطِيَ أَهْلُ الْإِنْجِيلِ الْإِنْجِيلَ فَعَمِلُوا بِهِ حَتَّى صَلَاةِ الْعَصْرِ ثُمَّ عَجَزُوا فَأُعْطُوا ‏ ‏قِيرَاطًا ‏ ‏قِيرَاطًا ‏ ‏ثُمَّ أُعْطِيتُمْ الْقُرْآنَ فَعَمِلْتُمْ بِهِ حَتَّى غَرَبَتْ الشَّمْسُ فَأُعْطِيتُمْ ‏ ‏قِيرَاطَيْنِ ‏ ‏قِيرَاطَيْنِ ‏ ‏فَقَالَ أَهْلُ التَّوْرَاةِ وَالْإِنْجِيلِ رَبَّنَا هَؤُلَاءِ أَقَلُّ عَمَلًا وَأَكْثَرُ أَجْرًا فَقَالَ هَلْ ظَلَمْتُكُمْ مِنْ أَجْرِكُمْ مِنْ شَيْءٍ فَقَالُوا لَا فَقَالَ فَضْلِي أُوتِيهِ مَنْ أَشَاءُ ‏","","",""],[5757,5757,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ إِنَّمَا ‏ ‏النَّاسُ كَالْإِبِلِ الْمِائَةِ لَا تَكَادُ تَجِدُ فِيهَا ‏ ‏رَاحِلَةً ‏","","",""],[5758,5758,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقُولُ عَلَى الْمِنْبَرِ ‏ ‏أَلَا إِنَّ ‏ ‏الْفِتْنَةَ ‏ ‏هَاهُنَا يُشِيرُ إِلَى الْمَشْرِقِ مِنْ حَيْثُ يَطْلُعُ قَرْنُ الشَّيْطَانِ ‏","","",""],[5759,5759,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يُقَاتِلُكُمْ ‏ ‏يَهُودُ ‏ ‏فَتُسَلَّطُونَ ‏ ‏عَلَيْهِمْ حَتَّى يَقُولَ الْحَجَرُ يَا مُسْلِمُ هَذَا يَهُودِيٌّ وَرَائِي فَاقْتُلْهُ ‏","","",""],[5760,5760,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَا أَنَا نَائِمٌ رَأَيْتُنِي أَطُوفُ ‏ ‏بِالْكَعْبَةِ ‏ ‏فَإِذَا رَجُلٌ ‏ ‏آدَمُ ‏ ‏سَبْطُ ‏ ‏الشَّعَرِ بَيْنَ رَجُلَيْنِ ‏ ‏يَنْطِفُ ‏ ‏رَأْسُهُ مَاءً فَقُلْتُ مَنْ هَذَا فَقَالُوا ‏ ‏ابْنُ مَرْيَمَ ‏ ‏فَذَهَبْتُ أَلْتَفِتُ فَإِذَا رَجُلٌ أَحْمَرُ ‏ ‏جَسِيمٌ ‏ ‏جَعْدُ ‏ ‏الرَّأْسِ أَعْوَرُ عَيْنِ الْيُمْنَى كَأَنَّ عَيْنَهُ عِنَبَةٌ ‏ ‏طَافِيَةٌ ‏ ‏فَقُلْتُ مَنْ هَذَا فَقَالُوا ‏ ‏الدَّجَّالُ ‏ ‏أَقْرَبُ النَّاسِ بِهِ شَبَهًا ‏ ‏ابْنُ قَطَنٍ ‏ ‏رَجُلٌ مِنْ ‏ ‏بَنِي الْمُصْطَلِقِ ‏","","",""],[5761,5761,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏قَالَ قَالَ ‏ ‏نَافِعٌ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَبِيعُ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ وَلَا يَخْطُبُ بَعْضُكُمْ عَلَى خِطْبَةِ بَعْضٍ ‏","","",""],[5762,5762,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَخْبَرَنِي ‏ ‏شُعَيْبٌ ‏ ‏قَالَ قَالَ ‏ ‏نَافِعٌ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الرُّؤْيَا الصَّالِحَةَ ‏ ‏قَالَ ‏ ‏نَافِعٌ ‏ ‏حَسِبْتُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏جُزْءٌ مِنْ سَبْعِينَ جُزْءًا مِنْ النُّبُوَّةِ ‏","","",""],[5763,5763,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏أَخْبَرَنَا ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَخْطُبَ الرَّجُلُ عَلَى خِطْبَةِ أَخِيهِ حَتَّى يَدَعَهَا الَّذِي خَطَبَهَا أَوَّلَ مَرَّةٍ أَوْ يَأْذَنَ لَهُ ‏","","",""],[5764,5764,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ امْرَأَةً وُجِدَتْ فِي بَعْضِ مَغَازِي النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَقْتُولَةً ‏ ‏فَأَنْكَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَتْلَ النِّسَاءِ وَالصِّبْيَانِ ‏","","",""],[5765,5765,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَيُّمَا مَمْلُوكٍ كَانَ بَيْنَ شَرِيكَيْنِ فَأَعْتَقَ أَحَدُهُمَا نَصِيبَهُ فَإِنَّهُ يُقَامُ فِي مَالِ الَّذِي أَعْتَقَ قِيمَةَ ‏ ‏عَدْلٍ ‏ ‏فَيُعْتِقُ إِنْ بَلَغَ ذَلِكَ مَالَهُ ‏","","",""],[5766,5766,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سَعِيدِ بْنِ عَمْرِو بْنِ سَعِيدِ بْنِ الْعَاصِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏سَعِيدِ بْنِ عَمْرٍو ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْيَدُ الْعُلْيَا خَيْرٌ مِنْ الْيَدِ السُّفْلَى ‏ ‏قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏فَلَمْ أَسْأَلْ ‏ ‏عُمَرَ ‏ ‏فَمَنْ سِوَاهُ مِنْ النَّاسِ ‏","","",""],[5767,5767,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَسْلَمُ ‏ ‏سَالَمَهَا اللَّهُ ‏ ‏وَغِفَارٌ ‏ ‏غَفَرَ اللَّهُ لَهَا ‏","","",""],[5768,5768,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْنُ أُمَّةٌ أُمِّيُّونَ لَا نَحْسُبُ وَلَا نَكْتُبُ الشَّهْرُ هَكَذَا وَهَكَذَا وَهَكَذَا وَقَبَضَ إِبْهَامَهُ فِي الثَّالِثَةِ ‏","","",""],[5769,5769,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ أَخِي ابْنِ شِهَابٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَعُثْمَانُ ‏ ‏يَمْشُونَ أَمَامَ الْجِنَازَةِ ‏","","",""],[5770,5770,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏وَيَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَفَاتِيحُ الْغَيْبِ خَمْسٌ ‏ { ‏إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ وَيُنَزِّلُ ‏ ‏الْغَيْثَ ‏ ‏وَيَعْلَمُ مَا فِي الْأَرْحَامِ وَمَا تَدْرِي نَفْسٌ مَاذَا تَكْسِبُ غَدًا وَمَا تَدْرِي نَفْسٌ بِأَيِّ أَرْضٍ تَمُوتُ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ ‏}","","",""],[5771,5771,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏وَيَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّمَا النَّاسُ كَالْإِبِلِ الْمِائَةِ لَا تَكَادُ تَجِدُ فِيهَا ‏ ‏رَاحِلَةً ‏ ‏وَقَالَ ‏ ‏يَعْقُوبُ ‏ ‏كَإِبِلٍ مِائَةٍ مَا فِيهَا ‏ ‏رَاحِلَةٌ ‏","","",""],[5772,5772,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَبْدِ الرَّحْمَنِ يَعْنِي الْجُمَحِيَّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلُّوا فِي بُيُوتِكُمْ لَا تَتَّخِذُوهَا قُبُورًا ‏","","",""],[5773,5773,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ السَّخْتِيَانِيِّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ شَرِبَ الْخَمْرَ فِي الدُّنْيَا لَمْ يَشْرَبْهَا فِي الْآخِرَةِ ‏","","",""],[5774,5774,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُوحٍ ‏ ‏أَنْبَأَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَمَلَ ‏ ‏مِنْ الْحَجَرِ الْأَسْوَدِ إِلَى الْحَجَرِ الْأَسْوَدِ ‏","","",""],[5775,5775,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ يَعْنِي ابْنَ عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏نَزَعَ ‏ ‏يَدًا مِنْ طَاعَةٍ فَلَا حُجَّةَ لَهُ يَوْمَ الْقِيَامَةِ وَمَنْ مَاتَ مُفَارِقًا لِلْجَمَاعَةِ فَقَدْ مَاتَ مِيتَةً جَاهِلِيَّةً ‏","","",""],[5776,5776,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّمَا النَّاسُ كَالْإِبِلِ الْمِائَةِ لَا تَكَادُ تَجِدُ فِيهَا ‏ ‏رَاحِلَةً ‏","","",""],[5777,5777,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏بِلَالًا ‏ ‏لَا يَدْرِي مَا اللَّيْلُ فَكُلُوا وَاشْرَبُوا حَتَّى يُنَادِيَ ‏ ‏ابْنُ أُمِّ مَكْتُومٍ ‏","","",""],[5778,5778,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏بِلَالًا ‏ ‏يُنَادِي بِلَيْلٍ فَكُلُوا وَاشْرَبُوا حَتَّى تَسْمَعُوا تَأْذِينَ ‏ ‏ابْنِ أُمِّ مَكْتُومٍ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏ابْنُ أُمِّ مَكْتُومٍ ‏ ‏رَجُلًا أَعْمَى لَا يُبْصِرُ لَا يُؤَذِّنُ حَتَّى يَقُولَ النَّاسُ أَذِّنْ قَدْ أَصْبَحْتَ ‏","","",""],[5779,5779,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏وَحُجَيْنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الْمُؤْمِنِ مَثَلُ شَجَرَةٍ لَا تَطْرَحُ وَرَقَهَا قَالَ ‏ ‏فَوَقَعَ ‏ ‏النَّاسُ فِي شَجَرِ الْبَدْوِ وَوَقَعَ فِي قَلْبِي أَنَّهَا النَّخْلَةُ فَاسْتَحْيَيْتُ أَنْ أَتَكَلَّمَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هِيَ النَّخْلَةُ قَالَ فَذَكَرْتُ ذَلِكَ ‏ ‏لِعُمَرَ ‏ ‏فَقَالَ يَا بُنَيَّ مَا مَنَعَكَ أَنْ تَتَكَلَّمَ فَوَاللَّهِ لَأَنْ تَكُونَ قُلْتَ ذَلِكَ أَحَبُّ إِلَيَّ مِنْ أَنْ يَكُونَ لِي كَذَا وَكَذَا ‏","","",""],[5780,5780,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنٌ ‏ ‏وَمُوسَى بْنُ دَاوُدَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ لِلْغَادِرِ ‏ ‏لِوَاءً ‏ ‏يَوْمَ الْقِيَامَةِ يُقَالُ أَلَا هَذِهِ ‏ ‏غَدْرَةُ ‏ ‏فُلَانٍ ‏","","",""],[5781,5781,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَرَّقَ نَخْلَ ‏ ‏بَنِي النَّضِيرِ ‏ ‏وَقَطَّعَ وَهِيَ ‏ ‏الْبُوَيْرَةُ ‏ ‏فَأَنْزَلَ اللَّهُ تَبَارَكَ وَتَعَالَى ‏ { ‏مَا قَطَعْتُمْ مِنْ ‏ ‏لِينَةٍ ‏ ‏أَوْ تَرَكْتُمُوهَا قَائِمَةً عَلَى أُصُولِهَا فَبِإِذْنِ اللَّهِ وَلِيُخْزِيَ الْفَاسِقِينَ ‏}","","",""],[5782,5782,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ امْرَأَةً وُجِدَتْ فِي بَعْضِ مَغَازِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَقْتُولَةً ‏ ‏فَأَنْكَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَتْلَ النِّسَاءِ وَالصِّبْيَانِ ‏","","",""],[5783,5783,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّهُ كَانَ ‏ ‏إِذَا صَلَّى الْجُمُعَةَ انْصَرَفَ فَصَلَّى سَجْدَتَيْنِ فِي بَيْتِهِ ثُمَّ قَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْنَعُ ذَلِكَ ‏","","",""],[5784,5784,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى إِذَا كَانَ ثَلَاثَةُ نَفَرٍ أَنْ ‏ ‏يَتَنَاجَى ‏ ‏اثْنَانِ دُونَ الثَّالِثِ ‏","","",""],[5785,5785,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ يَقُولُ ‏ ‏لَا تَتَبَايَعُوا الثَّمَرَةَ حَتَّى يَبْدُوَ صَلَاحُهَا نَهَى الْبَائِعَ وَالْمُشْتَرِيَ وَنَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمُزَابَنَةِ ‏ ‏أَنْ يَبِيعَ ثَمَرَةَ ‏ ‏حَائِطِهِ ‏ ‏إِنْ كَانَتْ نَخْلًا بِتَمْرٍ كَيْلًا وَإِنْ كَانَتْ كَرْمًا أَنْ يَبِيعَهُ بِزَبِيبٍ كَيْلًا وَإِنْ كَانَتْ زَرْعًا أَنْ يَبِيعَهُ بِكَيْلٍ مَعْلُومٍ نَهَى عَنْ ذَلِكَ كُلِّهِ ‏","","",""],[5786,5786,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَلَا إِنَّ أَحَدَكُمْ إِذَا مَاتَ عُرِضَ عَلَيْهِ مَقْعَدُهُ ‏ ‏بِالْغَدَاةِ ‏ ‏وَالْعَشِيِّ إِنْ كَانَ مِنْ أَهْلِ الْجَنَّةِ فَمِنْ أَهْلِ الْجَنَّةِ وَإِنْ كَانَ مِنْ أَهْلِ النَّارِ فَمِنْ أَهْلِ النَّارِ حَتَّى يَبْعَثَهُ اللَّهُ تَعَالَى يَوْمَ الْقِيَامَةِ ‏","","",""],[5787,5787,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَبِيعُ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ وَلَا يَخْطُبُ عَلَى خِطْبَةِ بَعْضٍ ‏","","",""],[5788,5788,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ ‏ ‏طَلَّقَ امْرَأَتَهُ وَهِيَ حَائِضٌ تَطْلِيقَةً وَاحِدَةً عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏عَبْدَ اللَّهِ ‏ ‏طَلَّقَ امْرَأَتَهُ تَطْلِيقَةً وَاحِدَةً وَهِيَ حَائِضٌ ‏ ‏فَأَمَرَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُرَاجِعَهَا وَيُمْسِكَهَا حَتَّى تَطْهُرَ ثُمَّ تَحِيضَ عِنْدَهُ حَيْضَةً أُخْرَى ثُمَّ يُمْهِلَهَا حَتَّى تَطْهُرَ مِنْ حَيْضَتِهَا فَإِنْ أَرَادَ أَنْ يُطَلِّقَهَا فَلْيُطَلِّقْهَا حِينَ تَطْهُرُ قَبْلَ أَنْ يُجَامِعَهَا فَتِلْكَ ‏ ‏الْعِدَّةُ ‏ ‏الَّتِي أَمَرَ اللَّهُ تَعَالَى أَنْ يُطَلَّقَ لَهَا النِّسَاءُ وَكَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏إِذَا سُئِلَ عَنْ ذَلِكَ فَقَالَ لِأَحَدِهِمْ أَمَّا أَنْتَ طَلَّقْتَ امْرَأَتَكَ مَرَّةً أَوْ مَرَّتَيْنِ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَنِي بِهَا فَإِنْ كُنْتَ طَلَّقْتَهَا ثَلَاثًا فَقَدْ حَرُمَتْ عَلَيْكَ حَتَّى تَنْكِحَ زَوْجًا غَيْرَكَ وَعَصَيْتَ اللَّهَ تَعَالَى فِيمَا أَمَرَكَ مِنْ طَلَاقِ امْرَأَتِكَ ‏","","",""],[5789,5789,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُقِيمَنَّ أَحَدُكُمْ الرَّجُلَ مِنْ مَجْلِسِهِ ثُمَّ يَجْلِسُ فِيهِ ‏","","",""],[5790,5790,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ حَرْبٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَيْفَ صَلَاةُ الْمُسَافِرِ يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏فَقَالَ أَمَّا أَنْتُمْ فَتَتَّبِعُونَ سُنَّةَ نَبِيِّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرْتُكُمْ وَأَمَّا أَنْتُمْ لَا تَتَّبِعُونَ سُنَّةَ نَبِيِّكُمْ لَمْ أُخْبِرْكُمْ قَالَ قُلْنَا فَخَيْرُ السُّنَنِ سُنَّةُ نَبِيِّنَا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏فَقَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا خَرَجَ مِنْ هَذِهِ ‏ ‏الْمَدِينَةِ ‏ ‏لَمْ يَزِدْ عَلَى رَكْعَتَيْنِ حَتَّى يَرْجِعَ إِلَيْهَا ‏","","",""],[5791,5791,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏أَخْبَرَنَا ‏ ‏بِشْرٌ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ بَارِكْ لَنَا فِي ‏ ‏مَدِينَتِنَا ‏ ‏وَبَارِكْ لَنَا فِي ‏ ‏شَامِنَا ‏ ‏وَبَارِكْ لَنَا فِي ‏ ‏يَمَنِنَا ‏ ‏وَبَارِكْ لَنَا فِي ‏ ‏صَاعِنَا ‏ ‏وَبَارِكْ لَنَا فِي ‏ ‏مُدِّنَا ‏","","",""],[5792,5792,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِي تَفُوتُهُ صَلَاةُ الْعَصْرِ فَكَأَنَّمَا ‏ ‏وُتِرَ ‏ ‏أَهْلَهُ وَمَالَهُ ‏","","",""],[5793,5793,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا إِنَّ مَثَلَ آجَالِكُمْ فِي آجَالِ الْأُمَمِ قَبْلَكُمْ كَمَا بَيْنَ صَلَاةِ الْعَصْرِ إِلَى ‏ ‏مُغَيْرِبَانِ الشَّمْسِ ‏","","",""],[5794,5794,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَسُرَيْجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ مُعْتَمِرًا فَحَالَ كُفَّارُ ‏ ‏قُرَيْشٍ ‏ ‏بَيْنَهُ وَبَيْنَ ‏ ‏الْبَيْتِ ‏ ‏فَنَحَرَ ‏ ‏هَدْيَهُ ‏ ‏وَحَلَقَ رَأْسَهُ ‏ ‏بِالْحُدَيْبِيَةِ ‏ ‏فَصَالَحَهُمْ عَلَى أَنْ يَعْتَمِرُوا الْعَامَ الْمُقْبِلَ وَلَا يَحْمِلَ السِّلَاحَ عَلَيْهِمْ ‏ ‏وَقَالَ ‏ ‏سُرَيْجٌ ‏ ‏وَلَا يَحْمِلَ سِلَاحًا إِلَّا سُيُوفًا ‏ ‏وَلَا يُقِيمَ بِهَا إِلَّا مَا أَحَبُّوا فَاعْتَمَرَ مِنْ الْعَامِ الْمُقْبِلِ فَدَخَلَهَا كَمَا كَانَ صَالَحَهُمْ فَلَمَّا أَنْ أَقَامَ ثَلَاثًا أَمَرُوهُ أَنْ يَخْرُجَ فَخَرَجَ ‏","","",""],[5795,5795,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَبَّدَ ‏ ‏رَأْسَهُ وَأَهْدَى فَلَمَّا قَدِمَ ‏ ‏مَكَّةَ ‏ ‏أَمَرَ نِسَاءَهُ أَنْ يَحْلِلْنَ قُلْنَ مَا لَكَ أَنْتَ لَا تَحِلُّ قَالَ ‏ ‏إِنِّي قَلَّدْتُ هَدْيِي ‏ ‏وَلَبَّدْتُ ‏ ‏رَأْسِي فَلَا أَحِلُّ حَتَّى أَحِلَّ مِنْ حَجَّتِي وَأَحْلِقَ رَأْسِي ‏","","",""],[5796,5796,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الظُّهْرَ وَالْعَصْرَ وَالْمَغْرِبَ وَالْعِشَاءَ ‏ ‏بِالْبَطْحَاءِ ‏ ‏ثُمَّ ‏ ‏هَجَعَ ‏ ‏هَجْعَةً ‏ ‏ثُمَّ دَخَلَ فَطَافَ ‏ ‏بِالْبَيْتِ ‏","","",""],[5797,5797,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏وَعُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏الدَّجَّالَ ‏ ‏أَعْوَرُ عَيْنِ الْيُمْنَى وَعَيْنُهُ الْأُخْرَى كَأَنَّهَا عِنَبَةٌ ‏ ‏طَافِيَةٌ ‏","","",""],[5798,5798,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَيَّانَ أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ يَعْنِي ابْنَ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏وَنَافِعٌ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ ‏ ‏يُصَلِّي عَلَى ‏ ‏رَاحِلَتِهِ ‏","","",""],[5799,5799,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَيَّانَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ عُبَيْدَةَ ‏ ‏سَمِعَ ‏ ‏ابْنُ عُمَرَ ‏ ‏رَجُلًا يَقُولُ ‏ ‏وَالْكَعْبَةِ ‏ ‏فَقَالَ لَا تَحْلِفْ بِغَيْرِ اللَّهِ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ حَلَفَ بِغَيْرِ اللَّهِ فَقَدْ كَفَرَ وَأَشْرَكَ ‏","","",""],[5800,5800,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ عُبَيْدَةَ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا عِنْدَ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏فَجِئْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏وَتَرَكْتُ عِنْدَهُ رَجُلًا مِنْ ‏ ‏كِنْدَةَ ‏ ‏فَجَاءَ الْكِنْدِيُّ مُرَوَّعًا فَقُلْتُ مَا وَرَاءَكَ قَالَ جَاءَ رَجُلٌ إِلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏آنِفًا فَقَالَ أَحْلِفُ ‏ ‏بِالْكَعْبَةِ ‏ ‏فَقَالَ احْلِفْ بِرَبِّ ‏ ‏الْكَعْبَةِ ‏ ‏فَإِنَّ ‏ ‏عُمَرَ ‏ ‏كَانَ يَحْلِفُ بِأَبِيهِ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَحْلِفْ بِأَبِيكَ فَإِنَّهُ مَنْ حَلَفَ بِغَيْرِ اللَّهِ فَقَدْ أَشْرَكَ ‏","","",""]];
